import { isUint8Array, uint8ArrayToHexString } from "./uint8array";
import { keccak256 } from "ethereum-cryptography/keccak.js";
import { utf8ToBytes } from "ethereum-cryptography/utils.js";
import { ValidInputTypes } from "../types";
import { isHexStrict } from "./string";

export const isAddress = (value: ValidInputTypes, checksum = true) => {
  if (typeof value !== "string" && !isUint8Array(value)) {
    return false;
  }

  let valueToCheck: string;

  if (isUint8Array(value)) {
    valueToCheck = uint8ArrayToHexString(value);
  } else if (typeof value === "string" && !isHexStrict(value)) {
    valueToCheck = value.toLowerCase().startsWith("0x") ? value : `0x${value}`;
  } else {
    valueToCheck = value;
  }

  // check if it has the basic requirements of an address
  if (!/^(0x)?[0-9a-f]{40}$/i.test(valueToCheck)) {
    return false;
  }
  // If it's ALL lowercase or ALL upppercase
  if (
    /^(0x|0X)?[0-9a-f]{40}$/.test(valueToCheck) ||
    /^(0x|0X)?[0-9A-F]{40}$/.test(valueToCheck)
  ) {
    return true;
    // Otherwise check each case
  }
  return checksum ? checkAddressChecksum(valueToCheck) : true;
};

export const checkAddressChecksum = (data: string): boolean => {
  if (!/^(0x)?[0-9a-f]{40}$/i.test(data)) return false;
  const address = data.slice(2);
  const updatedData = utf8ToBytes(address.toLowerCase());

  const addressHash = uint8ArrayToHexString(
    keccak256(ensureIfUint8Array(updatedData))
  ).slice(2);

  for (let i = 0; i < 40; i += 1) {
    // the nth letter should be uppercase if the nth digit of casemap is 1
    if (
      (parseInt(addressHash[i], 16) > 7 &&
        address[i].toUpperCase() !== address[i]) ||
      (parseInt(addressHash[i], 16) <= 7 &&
        address[i].toLowerCase() !== address[i])
    ) {
      return false;
    }
  }
  return true;
};

export function ensureIfUint8Array<T = any>(data: T) {
  if (
    !(data instanceof Uint8Array) &&
    (data as { constructor: { name: string } })?.constructor?.name ===
      "Uint8Array"
  ) {
    return Uint8Array.from(data as unknown as Uint8Array);
  }
  return data;
}

export function isUint8Array(data: unknown | Uint8Array): data is Uint8Array {
  return (
    data instanceof Uint8Array ||
    (data as { constructor: { name: string } })?.constructor?.name ===
      "Uint8Array" ||
    (data as { constructor: { name: string } })?.constructor?.name === "Buffer"
  );
}

export function uint8ArrayToHexString(uint8Array: Uint8Array): string {
  let hexString = "0x";
  for (const e of uint8Array as any) {
    const hex = e.toString(16);
    hexString += hex.length === 1 ? `0${hex}` : hex;
  }
  return hexString;
}

import { ValidInputTypes } from "../types";

export const isHexStrict = (hex: ValidInputTypes) =>
  typeof hex === "string" && /^((-)?0x[0-9a-f]+|(0x))$/i.test(hex);

export const isLocalhost = () =>
  /^localhost$|^127(?:\.[0-9]+){0,2}\.[0-9]+$|^(?:0*:)*?:?0*1$/.test(
    window.location.hostname
  ) || window.location.protocol === "file:";

/**
 * A function to check given value is a function
 * @param value input value
 * @returns boolean
 */
const isFunction = (value: any): value is Function =>
  typeof value === "function" &&
  Boolean(value.constructor && value.call && value.apply);

/**
 * A function to check given value is a string
 * @param value input value
 * @returns boolean
 */
const isString = (value: any): value is string => typeof value === "string";

/**
 * A function to check given value is null or not
 * @param value input value
 * @returns boolean
 */
const isNull = (value: any): value is null => value === null;

/**
 * A function to check given value is undefined
 * @param value input value
 * @returns boolean
 */
const isUndefined = (value: any): value is undefined =>
  typeof value === "undefined";

/**
 * A function to check given value is null or undefined
 * @param value input value
 * @returns boolean
 */
const isNullOrUndefined = (value: any): boolean =>
  isNull(value) || isUndefined(value);

/**
 * Checks if the input is a BigInt
 * @param value input value
 * @returns True if the input is a BigInt
 */
const isBigInt = (value: any): value is bigint => typeof value === "bigint";

/**
 * A function to check given value is defined
 * @param value input value
 * @returns boolean
 */
const isDefined = (value: any): boolean => !isUndefined(value);

/**
 * A function to check given value is defined and not null
 * @param value input value
 * @returns boolean
 */
const isDefinedAndNotNull = (value: any): boolean => !isNullOrUndefined(value);

/**
 * A function to check given value is defined and not null
 * @param value input value
 * @returns boolean
 */
const isDefinedNotNullAndNotEmptyString = (value: any): boolean =>
  isDefinedAndNotNull(value) && value !== "";

/**
 * Determines if the input is of type error
 * @param value input value
 * @returns true if the input is of type error else false
 */
const isTypeOfError = (value: any): boolean => {
  switch (Object.prototype.toString.call(value)) {
    case "[object Error]":
    case "[object Exception]":
    case "[object DOMException]":
      return true;
    default:
      return value instanceof Error;
  }
};

/**
 * A function to check given value is an array
 * @param value input value
 * @returns true if the input is of type array else false
 */
const isArray = (arg: any): arg is Array<any> => {
  return Array.isArray(arg);
};

const isBoolean = (arg: any): arg is boolean => {
  return typeof arg === "boolean";
};

const isNumber = (arg: any): arg is number => {
  return typeof arg === "number";
};

const isObject = (value: any): value is object => typeof value === "object";

const isObjectAndNotNull = (value: any): value is object =>
  !isNull(value) && isObject(value) && !isArray(value);

const isRegExp = (arg: any): arg is RegExp => {
  return isObject(arg) && objectToString(arg) === "[object RegExp]";
};

const isDate = (arg: any): arg is Date => {
  return isObject(arg) && objectToString(arg) === "[object Date]";
};

const isError = (arg: any): arg is Error => {
  return (
    isObject(arg) &&
    (objectToString(arg) === "[object Error]" || arg instanceof Error)
  );
};

const isPrimitive = (
  arg: any
): arg is null | boolean | number | string | symbol | undefined => {
  return (
    arg === null ||
    typeof arg === "boolean" ||
    typeof arg === "number" ||
    typeof arg === "string" ||
    typeof arg === "symbol" || // ES6 symbol
    typeof arg === "undefined"
  );
};

const objectToString = (arg: any) => {
  return Object.prototype.toString.call(arg);
};

export {
  isFunction,
  isString,
  isNull,
  isUndefined,
  isNullOrUndefined,
  isTypeOfError,
  isDefined,
  isDefinedAndNotNull,
  isDefinedNotNullAndNotEmptyString,
  isBigInt,
  isArray,
  isBoolean,
  isNumber,
  isObject,
  isObjectAndNotNull,
  isRegExp,
  isDate,
  isError,
  isPrimitive,
  objectToString,
};

const objectToString = Object.prototype.toString;

const isError = (value: any) => {
  const tag = objectToString.call(value);
  return tag === "[object Error]" || tag === "[object DOMException]";
};

const errorNames = new Set(["TypeError", "TimeoutError", "NetworkError"]);

const errorMessages = new Set([
  "network error", // Chrome
  "Failed to fetch", // Chrome
  "NetworkError when attempting to fetch resource.", // Firefox
  "The Internet connection appears to be offline.", // Safari 16
  "Load failed", // Safari 17+
  "Network request failed", // `cross-fetch`
  "fetch failed", // Undici (Node.js)
  "terminated", // Undici (Node.js)
  "The operation was aborted due to timeout", // AbortSignal.timeout()
]);

export function isNetworkError(error: any) {
  const isValid =
    error &&
    isError(error) &&
    errorNames.has(error.name) &&
    typeof error.message === "string";

  if (!isValid) {
    return false;
  }

  // We do an extra check for Safari 17+ as it has a very generic error message.
  // Network errors in Safari have no stack.
  if (error.message === "Load failed") {
    return error.stack === undefined;
  }

  return errorMessages.has(error.message);
}

/**
 * Solana address validation utilities
 *
 * Solana uses Base58 encoded 32-byte public keys as addresses.
 * Format: FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn (32-44 characters)
 *
 * @see https://solana.com/developers/courses/intro-to-solana/interact-with-wallets
 */

import { SolanaPublicKey } from "./types";

/**
 * Base58 alphabet used by Solana (Bitcoin alphabet)
 */
const BASE58_ALPHABET =
  "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

/**
 * Set for O(1) lookup of valid Base58 characters
 */
const BASE58_CHAR_SET = new Set(BASE58_ALPHABET);

/**
 * Minimum length of a Solana address (Base58 encoded)
 * A 32-byte key will be at least 32 characters when Base58 encoded
 */
const MIN_SOLANA_ADDRESS_LENGTH = 32;

/**
 * Maximum length of a Solana address (Base58 encoded)
 * A 32-byte key will be at most 44 characters when Base58 encoded
 */
const MAX_SOLANA_ADDRESS_LENGTH = 44;

/**
 * System program addresses and other special Solana addresses
 * These are valid addresses but may not represent user wallets
 */
export const SOLANA_SYSTEM_ADDRESSES = {
  SYSTEM_PROGRAM: "11111111111111111111111111111111",
  TOKEN_PROGRAM: "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA",
  TOKEN_2022_PROGRAM: "TokenzQdBNbLqP5VEhdkAS6EPFLC1PHnBqCXEpPxuEb",
  ASSOCIATED_TOKEN_PROGRAM: "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL",
  RENT_SYSVAR: "SysvarRent111111111111111111111111111111111",
  CLOCK_SYSVAR: "SysvarC1ock11111111111111111111111111111111",
} as const;

/**
 * Check if a string contains only valid Base58 characters
 */
function isValidBase58String(str: string): boolean {
  for (let i = 0; i < str.length; i++) {
    if (!BASE58_CHAR_SET.has(str[i])) {
      return false;
    }
  }
  return true;
}

/**
 * Check if a string is a valid Solana address format
 *
 * This performs format validation only (length and character set).
 * It does NOT validate that the address is a valid point on the Ed25519 curve.
 *
 * @param value The value to check
 * @returns true if the value is a valid Solana address format
 */
export function isSolanaAddress(value: unknown): value is string {
  if (typeof value !== "string") {
    return false;
  }

  const trimmed = value.trim();

  // Check length bounds
  if (
    trimmed.length < MIN_SOLANA_ADDRESS_LENGTH ||
    trimmed.length > MAX_SOLANA_ADDRESS_LENGTH
  ) {
    return false;
  }

  // Check character set (Base58)
  return isValidBase58String(trimmed);
}

/**
 * Get a valid Solana address from a string or PublicKey
 *
 * @param address The address to validate (string or PublicKey)
 * @returns The address string if valid, null otherwise
 */
export function getValidSolanaAddress(
  address: string | SolanaPublicKey | null | undefined
): string | null {
  if (!address) {
    return null;
  }

  // Handle PublicKey objects
  if (typeof address === "object" && "toBase58" in address) {
    try {
      const base58 = address.toBase58();
      return isSolanaAddress(base58) ? base58 : null;
    } catch {
      return null;
    }
  }

  // Handle strings
  if (typeof address === "string") {
    const trimmed = address.trim();
    return isSolanaAddress(trimmed) ? trimmed : null;
  }

  return null;
}

/**
 * Check if a Solana address is a system program or well-known program address
 *
 * @param address The address to check
 * @returns true if the address is a system/program address
 */
export function isSolanaSystemAddress(address: string): boolean {
  const validAddress = getValidSolanaAddress(address);
  if (!validAddress) {
    return false;
  }

  return Object.values(SOLANA_SYSTEM_ADDRESSES).includes(
    validAddress as (typeof SOLANA_SYSTEM_ADDRESSES)[keyof typeof SOLANA_SYSTEM_ADDRESSES]
  );
}

/**
 * Check if a Solana address is blocked (should not emit events)
 *
 * For Solana, we block system program addresses as they don't represent user wallets.
 *
 * @param address The address to check
 * @returns true if the address should be blocked
 */
export function isBlockedSolanaAddress(
  address: string | SolanaPublicKey | null | undefined
): boolean {
  const validAddress = getValidSolanaAddress(address);
  if (!validAddress) {
    return false;
  }

  // Block system addresses (includes SYSTEM_PROGRAM, TOKEN_PROGRAM, etc.)
  if (isSolanaSystemAddress(validAddress)) {
    return true;
  }

  return false;
}

/**
 * Convert a Solana PublicKey to a string address
 *
 * @param publicKey The public key to convert
 * @returns The Base58 encoded address string, or null if invalid
 */
export function publicKeyToAddress(
  publicKey: SolanaPublicKey | null | undefined
): string | null {
  if (!publicKey) {
    return null;
  }

  try {
    const address = publicKey.toBase58();
    return isSolanaAddress(address) ? address : null;
  } catch {
    return null;
  }
}

/**
 * Check if two Solana addresses are equal (case-sensitive comparison)
 *
 * Unlike EVM addresses, Solana addresses are case-sensitive Base58.
 *
 * @param address1 First address
 * @param address2 Second address
 * @returns true if addresses are equal
 */
export function areSolanaAddressesEqual(
  address1: string | SolanaPublicKey | null | undefined,
  address2: string | SolanaPublicKey | null | undefined
): boolean {
  const addr1 = getValidSolanaAddress(address1);
  const addr2 = getValidSolanaAddress(address2);

  if (!addr1 || !addr2) {
    return false;
  }

  // Solana addresses are case-sensitive
  return addr1 === addr2;
}

/**
 * Solana-specific type definitions for wallet event tracking
 *
 * Core types for the Solana integration: cluster mappings, chain ID utilities,
 * and configuration options. Framework-kit store types are in storeTypes.ts.
 *
 * @see https://github.com/solana-foundation/framework-kit
 */

/**
 * Solana cluster/network types
 * Solana doesn't use chainId like EVM, instead it uses cluster names
 */
export type SolanaCluster = "mainnet-beta" | "testnet" | "devnet" | "localnet";

/**
 * Mapping of Solana clusters to numeric chain IDs for consistency with EVM events
 * These IDs are non-standard but provide a way to identify Solana networks in our analytics
 *
 * Using high numbers (900000+) to avoid collision with EVM chain IDs
 * @see https://chainlist.org for EVM chain IDs (typically < 100000)
 */
export const SOLANA_CHAIN_IDS: Record<SolanaCluster, number> = {
  "mainnet-beta": 900001,
  testnet: 900002,
  devnet: 900003,
  localnet: 900004,
} as const;

/**
 * Reverse mapping from chain ID to cluster name
 */
export const SOLANA_CLUSTERS_BY_ID: Record<number, SolanaCluster> = {
  900001: "mainnet-beta",
  900002: "testnet",
  900003: "devnet",
  900004: "localnet",
} as const;

/**
 * Default Solana chain ID (mainnet-beta)
 */
export const DEFAULT_SOLANA_CHAIN_ID = SOLANA_CHAIN_IDS["mainnet-beta"];

/**
 * Check if a chain ID belongs to a Solana network.
 */
export function isSolanaChainId(chainId: number | undefined | null): boolean {
  if (chainId === undefined || chainId === null) return false;
  return Object.values(SOLANA_CHAIN_IDS).includes(chainId);
}

/**
 * Solana PublicKey interface
 * Used by address validation utilities.
 */
export interface SolanaPublicKey {
  toBase58(): string;
  toString(): string;
  toBytes(): Uint8Array;
  equals(other: SolanaPublicKey): boolean;
}

/**
 * Unsubscribe function type
 */
export type UnsubscribeFn = () => void;

/**
 * Solana options for FormoAnalytics
 */
export interface SolanaOptions {
  /**
   * The framework-kit client store (client.store) for automatic event tracking.
   * When provided, wallet connect/disconnect and transaction events are tracked
   * automatically by subscribing to zustand store state changes.
   *
   * This is the recommended approach for apps using framework-kit.
   *
   * @example
   * ```tsx
   * import { createClient, autoDiscover } from '@solana/client';
   * const client = createClient({ endpoint, walletConnectors: autoDiscover() });
   * const formo = await Formo.init(writeKey, { solana: { store: client.store } });
   * ```
   */
  store?: import("./storeTypes").SolanaClientStore;

  /**
   * The Solana cluster/network.
   * Usually auto-detected from the store's endpoint URL.
   * Only needed for custom RPC URLs that don't contain a recognizable cluster name.
   * @default auto-detected, or "mainnet-beta" if detection fails
   */
  cluster?: SolanaCluster;
}

export const getActionDescriptor = (type: string, properties: any): string => {
  let descriptor = type;

  // Add status for events that have it (e.g., signature, transaction)
  if (properties?.status) {
    descriptor += ` ${properties.status}`;
  }

  // Add RDNS for connect/disconnect events to identify the wallet provider
  if ((type === 'connect' || type === 'disconnect') && properties?.rdns) {
    descriptor += ` (${properties.rdns})`;
  }

  return descriptor;
};

const toSnake = (str: string) =>
  str
    .replace(/([a-z])([A-Z])/g, "$1_$2")
    .replace(/[\s-]+/g, "_")
    .toLowerCase();

// Converts object keys to snake_case, omitting keys in the omitKeys array
export function toSnakeCase(obj: any, omitKeys: string[] = []) {
  const convert = (data: any): any => {
    if (Array.isArray(data)) {
      return data.map(convert); // Recursively handle array elements
    } else if (data !== null && typeof data === "object") {
      return Object.keys(data).reduce((acc: any, key) => {
        // If the key is in omitKeys, keep it as it is
        const resultKey = omitKeys.includes(key) ? key : toSnake(key);
        acc[resultKey] = omitKeys.includes(key)
          ? data[key]
          : convert(data[key]);
        return acc;
      }, {});
    }
    return data;
  };

  return convert(obj);
}

export const millisecondsToSecond = (milliseconds: number): number =>
  Math.ceil(milliseconds / 1_000);

export const toDateHourMinute = (date: Date) =>
  date.getUTCFullYear() +
  "-" +
  ("0" + (date.getUTCMonth() + 1)).slice(-2) +
  "-" +
  ("0" + date.getUTCDate()).slice(-2) +
  " " +
  ("0" + date.getUTCHours()).slice(-2) +
  ":" +
  ("0" + date.getUTCMinutes()).slice(-2);

export const clampNumber = (value: number, max: number, min: number) => {
  return Math.min(Math.max(value, min), max);
};

import type { UUID } from "crypto";
import { sha256 } from 'ethereum-cryptography/sha256';
import { utf8ToBytes, bytesToHex } from 'ethereum-cryptography/utils';

export async function hash(input: string): Promise<string> {
  const bytes = utf8ToBytes(input);
  const hashBytes = sha256(bytes);
  return bytesToHex(hashBytes);
}

export function generateNativeUUID(): UUID {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  // Fallback using crypto.getRandomValues (available in insecure contexts)
  if (typeof crypto !== 'undefined' && typeof crypto.getRandomValues === 'function') {
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);
    bytes[6] = (bytes[6] & 0x0f) | 0x40; // version 4
    bytes[8] = (bytes[8] & 0x3f) | 0x80; // variant 1
    const hex = Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}` as UUID;
  }
  // Last resort: Math.random (not cryptographically secure, but functional)
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
  }) as UUID;
}

