/**
 * Traffic-source value sanitization.
 *
 * Vulnerability scanners (e.g. Acunetix) crawl customer sites injecting XSS
 * probes such as `javascript:domxssExecutionSink(1,"'\"><xsstag>()locxss")`
 * or `<script>alert(1)</script>` into every query parameter. Without
 * validation those payloads are captured verbatim as utm_* / click-id / ref
 * values, persisted as sticky session traffic sources, and pollute the
 * customer's attribution reporting. Each field class gets the tightest rule
 * its legitimate values allow (verified against production data):
 *
 * - Click IDs are opaque platform-generated tokens (base64url-ish); every
 *   legitimate production value matches the strict token pattern.
 * - Referral codes are short tokens; >99.5% of production values match the
 *   strict pattern and none of the remainder are legitimate (scanner
 *   payloads, mangled encodings, URLs glued to codes).
 * - UTM values are free-form (spaces, unicode, `+` are legitimate), so they
 *   only reject markup/quote characters, dangerous URL schemes, control and
 *   zero-width characters, and absurd lengths.
 *
 * Invalid values are dropped to "" — the same representation as "parameter
 * absent" — rather than repaired, so a poisoned value can never be persisted
 * or reported.
 */

const CLICK_ID_PATTERN = /^[A-Za-z0-9._-]{1,255}$/;

const REF_PATTERN = /^[A-Za-z0-9._-]{1,64}$/;

const UTM_MAX_LENGTH = 255;

// Markup/quote/backslash characters plus C0/C1 control characters and
// zero-width / bidi / BOM / replacement characters (mangled-encoding
// markers). Explicit ranges instead of \p{C} to avoid the `u`-flag
// property-escape requirement.
const UTM_FORBIDDEN_CHARS =
  /[<>"'`\\\u0000-\u001f\u007f-\u009f\u200b-\u200f\u2028-\u202e\u2060\ufeff\ufffd]/;

// Values smuggling an executable/URL scheme, e.g. `javascript:alert(1)`.
const FORBIDDEN_SCHEME_PREFIX = /^\s*(javascript|data|vbscript):/i;

const sanitizeClickId = (value: string): string =>
  CLICK_ID_PATTERN.test(value) ? value : "";

const sanitizeRef = (value: string): string =>
  REF_PATTERN.test(value) ? value : "";

const sanitizeUtm = (value: string): string =>
  value.length <= UTM_MAX_LENGTH &&
  !UTM_FORBIDDEN_CHARS.test(value) &&
  !FORBIDDEN_SCHEME_PREFIX.test(value)
    ? value
    : "";

const CLICK_ID_KEYS: ReadonlySet<string> = new Set(CLICK_ID_PARAMS);

/**
 * Sanitize every traffic-source field of a (possibly sparse) traffic-source
 * object. `referrer` is left untouched: it is a browser-set URL already
 * handled by redactUrl, not an attacker-controlled query parameter. Unknown
 * keys fall through to the UTM rule, the most permissive one.
 */
const sanitizeTrafficSources = <T extends Partial<ITrafficSource>>(
  trafficSources: T
): T => {
  const result: Record<string, unknown> = { ...trafficSources };
  for (const key of Object.keys(result)) {
    const value = result[key];
    if (typeof value !== "string" || value === "" || key === "referrer") {
      continue;
    }
    if (CLICK_ID_KEYS.has(key)) {
      result[key] = sanitizeClickId(value);
    } else if (key === "ref") {
      result[key] = sanitizeRef(value);
    } else {
      result[key] = sanitizeUtm(value);
    }
  }
  return result as T;
};

export { sanitizeClickId, sanitizeRef, sanitizeUtm, sanitizeTrafficSources };

import { AnonymousID } from "../types";
import { generateNativeUUID } from "../utils";
import { cookie } from "../storage";
import {
  getIdentityCookieDomain,
  getIdentityCookieSecurity,
} from "../storage/cookiePolicy";

const generateAnonymousId = (key: string, crossSubdomainCookies?: boolean): AnonymousID => {
  const storedAnonymousId = cookie().get(key);
  const anonymousId = (
    storedAnonymousId && typeof storedAnonymousId === "string"
      ? storedAnonymousId
      : generateNativeUUID()
  ) as AnonymousID;
  const domain = getIdentityCookieDomain(crossSubdomainCookies);
  // Re-set the cookie with the configured scope. When crossSubdomainCookies
  // is true, this migrates legacy host-only cookies on the current host to the apex
  // domain. Note: host-only cookies on other hosts (e.g. a cookie set on
  // example.com is not visible from app.example.com) cannot be migrated
  // until the user revisits that host.
  cookie().set(key, anonymousId, {
    expires: new Date(Date.now() + 1000 * 60 * 60 * 24 * 365).toUTCString(), // 1 year
    path: "/",
    // Consistent with the other identity cookies: SameSite=Lax +
    // Secure (HTTPS only). Orthogonal to `domain` cross-subdomain
    // sharing and to JS document.cookie read/write.
    ...getIdentityCookieSecurity(),
    ...(domain ? { domain } : {}),
  });
  return anonymousId;
};

export { generateAnonymousId };

// src/browser/browsers.ts
export type BrowserName =
  | "brave"
  | "chrome"
  | "edge"
  | "firefox"
  | "safari"
  | "opera"
  | "unknown";

let inFlight: Promise<BrowserName> | null = null;
let cached: BrowserName | null = null;

function getUA(): string {
  try {
    return typeof globalThis.navigator !== "undefined"
      ? globalThis.navigator.userAgent
      : "";
  } catch {
    return "";
  }
}

async function isBraveHeuristic(): Promise<boolean> {
  const nav: any =
    typeof globalThis.navigator !== "undefined"
      ? (globalThis.navigator as any)
      : undefined;
  if (!nav) return false;

  try {
    if (nav.brave?.isBrave) {
      const ok = await nav.brave.isBrave().catch(() => false);
      if (ok) return true;
    }
  } catch {}

  try {
    const brands: Array<{ brand: string; version: string }> | undefined =
      nav.userAgentData?.brands;
    if (brands?.some((b) => /Brave/i.test(b.brand))) return true;
  } catch {}

  try {
    if (/Brave/i.test(nav.userAgent)) return true;
  } catch {}

  return false;
}

function classifyNonBrave(ua: string): BrowserName {
  if (/Firefox\/\d+/i.test(ua)) return "firefox";
  if (/Edg\/\d+/i.test(ua)) return "edge";
  if (/OPR\/\d+/i.test(ua)) return "opera";
  if (/Safari\/\d+/i.test(ua) && !/Chrome\/\d+/i.test(ua)) return "safari";
  if (/Chrome\/\d+/i.test(ua)) return "chrome";
  return "unknown";
}

export function detectBrowser(): Promise<BrowserName> {
  if (cached) return Promise.resolve(cached);
  if (inFlight) return inFlight;

  inFlight = (async () => {
    const ua = getUA();
    const brave = await isBraveHeuristic().catch(() => false);
    cached = brave ? "brave" : classifyNonBrave(ua);
    return cached;
  })().finally(() => {
    inFlight = null; // subsequent calls hit cache
  });

  return inFlight;
}

import { Address, APIEvent, Options } from "../types";
import { logger } from "../logger";
import { IEventQueue } from "../queue";
import { EventFactory } from "./EventFactory";
import { IEventFactory, IEventManager } from "./type";
import { isBlockedAddress } from "../utils/address";

/**
 * A service to generate valid event payloads and queue them for processing
 */
class EventManager implements IEventManager {
  eventQueue: IEventQueue;
  eventFactory: IEventFactory;

  /**
   *
   * @param eventQueue Event queue instance
   * @param options Optional configuration (referral parsing, etc.)
   */
  constructor(eventQueue: IEventQueue, options?: Options) {
    this.eventQueue = eventQueue;
    this.eventFactory = new EventFactory(options);
  }

  /**
   * Consumes a new incoming event
   * @param event Incoming event data
   */
  async addEvent(
    event: APIEvent,
    address?: Address,
    userId?: string
  ): Promise<void> {
    const { callback, ..._event } = event;
    const formoEvent = await this.eventFactory.create(_event, address, userId);

    // Check if the final event has a blocked address - don't queue it
    if (formoEvent.address && isBlockedAddress(formoEvent.address)) {
      logger.warn(
        `Event blocked: Address ${formoEvent.address} is in the blocked list and cannot emit events`
      );
      return;
    }

    this.eventQueue.enqueue(formoEvent, (err, _, data) => {
      if (err) {
        logger.error("Error sending events:", err);
      } else logger.info(`Events sent successfully: ${data.length} events`);
      callback?.(err, _, data);
    });
  }

  /** Drop any buffered events (consent withdrawal / teardown). */
  clear(): void {
    this.eventQueue.clear();
  }
}

export { EventManager };

