  // byte total can be tracked incrementally (avoids an O(n) re-serialize
  // of the whole queue on every enqueue → O(n^2) overall).
  byteSize: number;
};

type IFormoEventFlushPayload = IFormoEventPayload & {
  sent_at: string;
};

type Batch = {
  data: IFormoEventFlushPayload[];
