/**
 * Configuration options for controlling tracking exclusions
 */
export interface TrackingOptions {
  excludeHosts?: string[];
  excludePaths?: string[];
  excludeChains?: ChainID[];
  /**
   * IANA timezone names to opt out of tracking entirely. When the visitor's
   * resolved timezone (via `Intl.DateTimeFormat().resolvedOptions().timeZone`)
   * matches one of these, no events are enqueued or sent - including `identify`
   * and `connect`. Matched case-insensitively against the full timezone string.
   *
   * Note: this is client-side, timezone-derived geolocation. It is best-effort
   * and can be bypassed (a VPN does not change the browser timezone, and users
   * can change their OS timezone). For authoritative jurisdiction blocking, use
   * server-side IP geolocation at your ingest endpoint instead.
   *
   * @example ["Europe/London", "America/New_York"]
   */
  excludeTimezones?: string[];
  /**
   * Additional query parameter names to strip from forwarded and stored URLs,
   * on top of a built-in always-on denylist (currently `privy_oauth_code`,
   * `privy_oauth_state`, and `privy_oauth_provider`) that cannot be disabled.
   * Matched case-insensitively. Excluded params are stripped from the captured
   * page URL, query string, per-parameter page properties, and referrer before
   * any event is sent. The URL hash/fragment is intentionally left untouched.
   *
   * Mirrors Mixpanel's `property_blacklist` and PostHog's `property_denylist`,
   * scoped here to URL query parameters.
   *
   * @example ["token", "access_token", "email", "signature"]
   */
  excludeQueryParams?: string[];
}

/**
 * Configuration options for controlling wallet event autocapture
 * All events are enabled by default unless explicitly set to false
 */
export interface AutocaptureOptions {
  /**
   * Track wallet connect events
   * @default true
   */
  connect?: boolean;

  /**
   * Track wallet disconnect events
   * @default true
   */
  disconnect?: boolean;

  /**
   * Track wallet signature events (personal_sign, eth_signTypedData_v4)
   * @default true
   */
  signature?: boolean;

  /**
   * Track wallet transaction events (eth_sendTransaction)
   * @default true
   */
  transaction?: boolean;

  /**
   * Track wallet chain change events
   * @default true
   */
  chain?: boolean;
}

/**
 * Configuration options for referral parameter parsing
 */
export interface ReferralOptions {
  /**
   * Custom query parameter names to check for referral codes
   * @default ["ref", "referral", "refcode", "af", "referrer"]
   * @example ["via", "partner", "source"] - will check ?via=CODE, ?partner=CODE, ?source=CODE
   */
  queryParams?: string[];

  /**
   * URL path pattern to extract referral code from
   * Should be a regex string that matches the path segment containing the referral code
   * The first capture group will be used as the referral code
   * @example "/r/([^/]+)" - will extract "01K17FKB" from "https://glider.fi/r/01K17FKB"
   */
  pathPattern?: string;
}

/**
 * Configuration options for Wagmi integration
 * Allows the SDK to hook into Wagmi v2 wallet events instead of wrapping EIP-1193 providers
 */
export interface WagmiOptions {
  /**
   * Wagmi config instance from createConfig()
   * The SDK will subscribe to this config's state changes to track wallet events
   */
  config: any;

  /**
   * Optional QueryClient instance from @tanstack/react-query
   * Required for tracking signature and transaction events via mutation cache
   * If not provided, only connection/disconnection/chain events will be tracked
   */
  queryClient?: any;
}

export interface Options {
  provider?: EIP1193Provider;
  tracking?: boolean | TrackingOptions;
  /**
   * When `true`, identity cookies (anonymous ID, user ID) are set on the
   * apex/root domain (e.g. `.example.com`), enabling cross-subdomain identity
   * sharing between app.example.com and www.example.com.
   *
   * When `false`, cookies are scoped to the current host only.
   *
   * Session cookies (wallet detection, current URL) always remain host-scoped.
   * Consent cookies are always apex-scoped independently for compliance.
   * @default true
   */
  crossSubdomainCookies?: boolean;
  /**
   * Control wallet event autocapture
   * - `false`: Disable all wallet autocapture
   * - `true`: Enable all wallet events (default)
   * - `AutocaptureOptions`: Granular control over specific events
   * @default true
   */
  autocapture?: boolean | AutocaptureOptions;
  /**
   * EVM provider tracking.
   * Set to `false` to disable all EVM provider detection and tracking
   * (EIP-1193, EIP-6963, window.ethereum). Useful for Solana-only apps
   * that don't need EVM wallet event capture.
   * @default true
   */
  evm?: boolean;
  /**
   * Wagmi integration configuration
   * When provided, the SDK will hook into Wagmi's event system instead of wrapping EIP-1193 providers
   * This replaces the default provider tracking with Wagmi's config.subscribe() and MutationCache
   * @requires wagmi@>=2.0.0
   * @requires @tanstack/react-query@>=5.0.0 (for mutation tracking)
   */
  wagmi?: WagmiOptions;
  /**
   * Solana integration configuration.
   * Pass `store: client.store` from framework-kit for automatic tracking of
   * wallet connect/disconnect and transaction events.
   *
   * For signMessage/signTransaction, use formo.signature() directly
   * (framework-kit doesn't track these in the store).
   *
   * @see https://github.com/solana-foundation/framework-kit
   */
  solana?: SolanaOptions;
  /**
   * Custom API host for sending events through your own domain to bypass ad blockers
   * - If not provided, events are sent directly to events.formo.so
   * - When provided, events are sent to your custom endpoint which should forward them to Formo
   * - Example: 'https://your-host-url.com/ingest' or '/api/analytics'
   * 
   * See https://docs.formo.so/sdks/web#proxy for setup instructions
   */
  apiHost?: string;
  flushAt?: number;
  flushInterval?: number;
  retryCount?: number;
  maxQueueSize?: number;
  logger?: {
    enabled?: boolean;
    levels?: LogLevel[];
  };
  /**
   * Configuration for referral parameter parsing from URLs
   * Allows customizing how referral codes are detected from query parameters and URL paths
   * @example { queryParams: ["via"], pathPattern: "/r/([^/]+)" }
   */
  referral?: ReferralOptions;
  /**
   * Optional error handler for analytics network failures.
   * Called when event flush fails after all retries.
   * If not provided, errors are silently swallowed.
   */
  errorHandler?: (err: Error) => void;
  ready?: (formo: IFormoAnalytics) => void;
}

