import { describe, it } from "mocha";
import { expect } from "chai";
import { toChecksumAddress } from "../../../src/utils";
import { isValidAddress, getValidAddress } from "../../../src/utils/address";
import { isAddress } from "../../../src/validators";

describe("Address handling bug fix", () => {
  describe("toChecksumAddress function", () => {
    it("should throw error when empty string is passed", () => {
      expect(() => toChecksumAddress("")).to.throw("Invalid address ");
    });

    it("should throw error when undefined is passed", () => {
      expect(() => toChecksumAddress(undefined as any)).to.throw("Invalid address undefined");
    });

    it("should throw error when null is passed", () => {
      expect(() => toChecksumAddress(null as any)).to.throw("Invalid address null");
    });

    it("should handle valid addresses correctly", () => {
      const validAddress = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";
      expect(() => toChecksumAddress(validAddress)).to.not.throw();
    });
  });

  describe("isValidAddress helper function", () => {
    it("should correctly identify empty strings as invalid", () => {
      const testAddress: string = "";
      expect(isValidAddress(testAddress)).to.be.false;
    });

    it("should correctly identify undefined as invalid", () => {
      const testAddress: string | undefined = undefined;
      expect(isValidAddress(testAddress)).to.be.false;
    });

    it("should correctly identify null as invalid", () => {
      const testAddress: string | null = null;
      expect(isValidAddress(testAddress)).to.be.false;
    });

    it("should correctly identify whitespace-only strings as invalid", () => {
      const testAddress: string = "   ";
      expect(isValidAddress(testAddress)).to.be.false;
    });

    it("should correctly identify valid addresses", () => {
      const testAddress: string = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";
      expect(isValidAddress(testAddress)).to.be.true;
    });

    it("should correctly identify non-empty strings as valid", () => {
      const testAddress: string = "0x1234567890123456789012345678901234567890";
      expect(isValidAddress(testAddress)).to.be.true;
    });

    it("should correctly identify addresses with leading/trailing whitespace as valid", () => {
      const testAddress: string = "  0x1095bBe769fDab716A823d0f7149CAD713d20A13  ";
      expect(isValidAddress(testAddress)).to.be.true;
    });
  });

  describe("getValidAddress function", () => {
    it("should return trimmed valid address", () => {
      const testAddress = "  0x1095bBe769fDab716A823d0f7149CAD713d20A13  ";
      const result = getValidAddress(testAddress);
      expect(result).to.equal("0x1095bBe769fDab716A823d0f7149CAD713d20A13");
    });

    it("should return null for invalid addresses", () => {
      const testAddress = "invalid-address";
      const result = getValidAddress(testAddress);
      expect(result).to.be.null;
    });

    it("should return null for empty strings", () => {
      const testAddress = "";
      const result = getValidAddress(testAddress);
      expect(result).to.be.null;
    });

    it("should return null for whitespace-only strings", () => {
      const testAddress = "   ";
      const result = getValidAddress(testAddress);
      expect(result).to.be.null;
    });
  });

  describe("Comparison between isValidAddress and isAddress", () => {
    it("should handle invalid addresses differently", () => {
      const invalidAddresses = [
        "", // empty string
        "   ", // whitespace only
        "not-an-address", // invalid format
        "0x123", // too short
        "0x1234567890123456789012345678901234567890123456789012345678901234567890", // too long
      ];

      invalidAddresses.forEach(address => {
        // isValidAddress should return false for all invalid addresses
        expect(isValidAddress(address)).to.be.false;

        // isAddress should also return false for invalid addresses
        expect(isAddress(address)).to.be.false;
      });
    });

    it("should handle valid addresses consistently", () => {
      const validAddresses = [
        "0x1095bBe769fDab716A823d0f7149CAD713d20A13",
        "0x1234567890123456789012345678901234567890",
        "0x1095bBe769fDab716A823d0f7149CAD713d20A13  ", // with trailing whitespace
        "  0x1095bBe769fDab716A823d0f7149CAD713d20A13", // with leading whitespace
      ];

      validAddresses.forEach(address => {
        // isValidAddress should return true for valid addresses (after trimming)
        expect(isValidAddress(address)).to.be.true;

        // isAddress should return true for valid addresses (after trimming)
        expect(isAddress(address.trim())).to.be.true;
      });
    });
  });

  describe("Whitespace handling bug fix", () => {
    it("should handle addresses with whitespace without throwing errors", () => {
      const addressWithWhitespace = "  0x1095bBe769fDab716A823d0f7149CAD713d20A13  ";

      // This should not throw an error
      expect(() => {
        const validAddress = getValidAddress(addressWithWhitespace);
        if (validAddress) {
          toChecksumAddress(validAddress);
        }
      }).to.not.throw();
    });

    it("should properly trim addresses before validation", () => {
      const addressWithWhitespace = "  0x1095bBe769fDab716A823d0f7149CAD713d20A13  ";
      const trimmedAddress = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";

      expect(isValidAddress(addressWithWhitespace)).to.be.true;
      expect(getValidAddress(addressWithWhitespace)).to.equal(trimmedAddress);
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import { EventFactory } from "../../../src/event/EventFactory";
import { initStorageManager } from "../../../src/storage";

const TIMEZONE = { value: "UTC" };

function stubIntl(timeZone: string | undefined) {
  TIMEZONE.value = timeZone ?? "";
  Object.defineProperty(global, "Intl", {
    value: {
      DateTimeFormat: () => ({
        resolvedOptions: () => ({ timeZone: TIMEZONE.value }),
      }),
    },
    writable: true,
    configurable: true,
  });
}

async function resolveLocation(factory: EventFactory): Promise<string> {
  const event = await factory.generatePageEvent(undefined, undefined, {}, {});
  return (event.context as any).location as string;
}

describe("EventFactory.getLocation", () => {
  let jsdom: JSDOM;
  let factory: EventFactory;

  beforeEach(() => {
    jsdom = new JSDOM(
      "<!DOCTYPE html><html><head><title>Test</title></head><body></body></html>",
      { url: "https://example.com/test" }
    );
    Object.defineProperty(global, "window", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "document", {
      value: jsdom.window.document, writable: true, configurable: true,
    });
    Object.defineProperty(global, "location", {
      value: jsdom.window.location, writable: true, configurable: true,
    });
    Object.defineProperty(global, "globalThis", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "navigator", {
      value: jsdom.window.navigator, writable: true, configurable: true,
    });
    Object.defineProperty(global, "screen", {
      value: jsdom.window.screen, writable: true, configurable: true,
    });
    Object.defineProperty(global, "localStorage", {
      value: jsdom.window.localStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "sessionStorage", {
      value: jsdom.window.sessionStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "crypto", {
      value: { randomUUID: () => "00000000-0000-0000-0000-000000000000" },
      writable: true, configurable: true,
    });

    initStorageManager("test-write-key");
    factory = new EventFactory();
  });

  afterEach(() => {
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).location;
    delete (global as any).globalThis;
    delete (global as any).navigator;
    delete (global as any).screen;
    delete (global as any).Intl;
    delete (global as any).localStorage;
    delete (global as any).sessionStorage;
    delete (global as any).crypto;
    if (jsdom) jsdom.window.close();
  });

  it("returns '' when Intl reports UTC", async () => {
    stubIntl("UTC");
    expect(await resolveLocation(factory)).to.equal("");
  });

  it("returns '' when Intl reports an Etc/GMT offset zone", async () => {
    stubIntl("Etc/GMT+5");
    expect(await resolveLocation(factory)).to.equal("");
  });

  it("returns 'UA' for Europe/Kyiv", async () => {
    stubIntl("Europe/Kyiv");
    expect(await resolveLocation(factory)).to.equal("UA");
  });

  it("returns 'UA' for legacy Europe/Kiev", async () => {
    stubIntl("Europe/Kiev");
    expect(await resolveLocation(factory)).to.equal("UA");
  });

  it("returns 'MX' for America/Ciudad_Juarez", async () => {
    stubIntl("America/Ciudad_Juarez");
    expect(await resolveLocation(factory)).to.equal("MX");
  });

  it("returns '' for an unknown timezone", async () => {
    stubIntl("Mars/Jezero");
    expect(await resolveLocation(factory)).to.equal("");
  });

  it("returns 'US' for America/Phoenix (no comma-separated leak)", async () => {
    stubIntl("America/Phoenix");
    expect(await resolveLocation(factory)).to.equal("US");
  });

  it("returns 'GU' for Pacific/Guam (no comma-separated leak)", async () => {
    stubIntl("Pacific/Guam");
    expect(await resolveLocation(factory)).to.equal("GU");
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import { EventFactory } from "../../../src/event/EventFactory";
import { initStorageManager } from "../../../src/storage";

/**
 * EventFactory.create user_id resolution.
 *
 * An identify event asserts an explicit identity in its own payload (e.g. a
 * Privy DID for each wallet being clustered). It must keep that payload user_id
 * rather than being overwritten by the active-session user id passed in - that
 * overwrite would strip the DID from every clustering identify emitted with
 * setActive:false and break server-side wallet clustering.
 */
describe("EventFactory.create user_id resolution", () => {
  let jsdom: JSDOM;
  let eventFactory: EventFactory;

  const ADDRESS = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";
  const DID = "did:privy:abc123";

  beforeEach(() => {
    jsdom = new JSDOM(
      "<!DOCTYPE html><html><head></head><body></body></html>",
      { url: "https://formo.so/" }
    );
    Object.defineProperty(global, "window", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "document", {
      value: jsdom.window.document, writable: true, configurable: true,
    });
    Object.defineProperty(global, "location", {
      value: jsdom.window.location, writable: true, configurable: true,
    });
    Object.defineProperty(global, "globalThis", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "navigator", {
      value: jsdom.window.navigator, writable: true, configurable: true,
    });
    Object.defineProperty(global, "screen", {
      value: jsdom.window.screen, writable: true, configurable: true,
    });
    Object.defineProperty(global, "Intl", {
      value: {
        DateTimeFormat: () => ({
          resolvedOptions: () => ({ timeZone: "America/New_York" }),
        }),
      },
      writable: true, configurable: true,
    });
    Object.defineProperty(global, "localStorage", {
      value: jsdom.window.localStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "sessionStorage", {
      value: jsdom.window.sessionStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "crypto", {
      value: { randomUUID: () => "12345678-1234-1234-1234-123456789abc" },
      writable: true, configurable: true,
    });

    initStorageManager("test-write-key");
    eventFactory = new EventFactory();
  });

  afterEach(() => {
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).location;
    delete (global as any).globalThis;
    delete (global as any).navigator;
    delete (global as any).screen;
    delete (global as any).Intl;
    delete (global as any).localStorage;
    delete (global as any).sessionStorage;
    delete (global as any).crypto;
    if (jsdom) jsdom.window.close();
  });

  it("keeps the identify payload user_id (DID) over the active-session user id", async () => {
    // A clustering identify (setActive:false) passes the DID in the payload but
    // the active-session user id is unchanged (here: undefined).
    const result = await eventFactory.create(
      { type: "identify", address: ADDRESS, userId: DID } as any,
      ADDRESS,
      undefined
    );
    expect(result.user_id).to.equal(DID);
  });

  it("keeps the payload DID even when the active-session user id is a different value", async () => {
    const result = await eventFactory.create(
      { type: "identify", address: ADDRESS, userId: DID } as any,
      ADDRESS,
      "some-other-user"
    );
    expect(result.user_id).to.equal(DID);
  });

  it("falls back to the active-session user id when the identify payload has none", async () => {
    const result = await eventFactory.create(
      { type: "identify", address: ADDRESS } as any,
      ADDRESS,
      "session-user"
    );
    expect(result.user_id).to.equal("session-user");
  });

  it("uses the active-session user id for non-identify events", async () => {
    const result = await eventFactory.create(
      { type: "track", event: "custom" } as any,
      ADDRESS,
      "session-user"
    );
    expect(result.user_id).to.equal("session-user");
  });
});

