      await eventManager.addEvent(apiEvent, undefined, userId);

      expect(enqueueSpy.calledOnce).to.be.true;
      const [formoEvent] = enqueueSpy.firstCall.args;
      expect(formoEvent.user_id).to.equal("user-123");
