      const apiEvent: APIEvent = {
        type: "chain",
        chainId: 1,
        address: "0x1234567890123456789012345678901234567890",
      };
      await eventManager.addEvent(apiEvent);
      expect(enqueueSpy.calledOnce).to.be.true;
      expect(enqueueSpy.firstCall.args[0].type).to.equal("chain");
    });

    it("should handle track event type", async () => {
      const apiEvent: APIEvent = {
        type: "track",
        event: "button_click",
      };
      await eventManager.addEvent(apiEvent);
      expect(enqueueSpy.calledOnce).to.be.true;
      expect(enqueueSpy.firstCall.args[0].type).to.equal("track");
    });
  });

  describe("address validation", () => {
    it("should allow valid addresses", async () => {
      const validAddresses = [
        "0x1234567890123456789012345678901234567890",
        "0xabcdef1234567890abcdef1234567890abcdef12",
        "0xABCDEF1234567890ABCDEF1234567890ABCDEF12",
      ];

      for (const address of validAddresses) {
        enqueueSpy.resetHistory();
        const apiEvent: APIEvent = {
          type: "connect",
          chainId: 1,
          address,
        };

        await eventManager.addEvent(apiEvent, address);
        expect(enqueueSpy.calledOnce).to.be.true;
      }
    });

    it("should block blocked addresses case-insensitively", async () => {
      const blockedAddresses = [
        "0x0000000000000000000000000000000000000000",
        "0x000000000000000000000000000000000000dead",
        "0x000000000000000000000000000000000000DEAD",
        "0x000000000000000000000000000000000000dEaD",
      ];

      for (const address of blockedAddresses) {
        enqueueSpy.resetHistory();
        const apiEvent: APIEvent = {
          type: "connect",
          chainId: 1,
          address,
        };

        await eventManager.addEvent(apiEvent, address);
        expect(enqueueSpy.called).to.be.false;
      }
    });
  });

  describe("clear", () => {
    it("delegates to the event queue's clear()", () => {
      eventManager.clear();
      expect((mockEventQueue.clear as sinon.SinonSpy).calledOnce).to.be.true;
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import { EventFactory } from "../../../src/event/EventFactory";
import { initStorageManager, session } from "../../../src/storage";
import { SESSION_TRAFFIC_SOURCE_KEY } from "../../../src/constants";

/**
 * Test suite for page event property parsing functionality
 * Tests the actual EventFactory.generatePageEvent method
 */
describe("Page Event Property Parsing", () => {
  let jsdom: JSDOM;
  let eventFactory: EventFactory;

  beforeEach(() => {
    // Set up JSDOM with a base URL
    jsdom = new JSDOM("<!DOCTYPE html><html><head><title>Test Page</title></head><body></body></html>", {
      url: "https://formo.so/",
    });

    // Make JSDOM's window and document available globally
    Object.defineProperty(global, 'window', {
      value: jsdom.window,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'document', {
      value: jsdom.window.document,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'location', {
      value: jsdom.window.location,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'globalThis', {
      value: jsdom.window,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'navigator', {
      value: jsdom.window.navigator,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'screen', {
      value: jsdom.window.screen,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'devicePixelRatio', {
      value: 1,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'innerWidth', {
      value: 1920,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'innerHeight', {
      value: 1080,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'Intl', {
      value: {
        DateTimeFormat: () => ({
          resolvedOptions: () => ({ timeZone: "America/New_York" }),
        }),
      },
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'localStorage', {
      value: jsdom.window.localStorage,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'sessionStorage', {
      value: jsdom.window.sessionStorage,
      writable: true,
      configurable: true,
    });
    Object.defineProperty(global, 'crypto', {
      value: {
        randomUUID: () => "12345678-1234-1234-1234-123456789abc",
      },
      writable: true,
      configurable: true,
    });

    // Initialize StorageManager
    initStorageManager('test-write-key');

    // Create EventFactory instance
    eventFactory = new EventFactory();
  });

  afterEach(() => {
    // Clean up globals
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).location;
    delete (global as any).globalThis;
    delete (global as any).navigator;
    delete (global as any).screen;
    delete (global as any).devicePixelRatio;
    delete (global as any).innerWidth;
    delete (global as any).innerHeight;
    delete (global as any).Intl;
    delete (global as any).localStorage;
    delete (global as any).sessionStorage;
    delete (global as any).crypto;

    // Clean up JSDOM
    if (jsdom) {
      jsdom.window.close();
    }
  });

  /**
   * Helper function to set mock location by creating a new JSDOM with the desired URL
   */
  function setMockLocation(url: string, referrer?: string) {
    // Close previous JSDOM
    if (jsdom) {
      jsdom.window.close();
    }

    // Create new JSDOM with the desired URL
    const options: ConstructorParameters<typeof JSDOM>[1] = { url };
    if (referrer !== undefined) options.referrer = referrer;
    jsdom = new JSDOM("<!DOCTYPE html><html><head><title>Test Page</title></head><body></body></html>", options);

    // Update globals
    (global as any).window = jsdom.window;
    (global as any).document = jsdom.window.document;
    (global as any).location = jsdom.window.location;
    (global as any).globalThis = jsdom.window;
  }

  /**
   * Helper to test page properties through the actual EventFactory.generatePageEvent method
   */
  async function getPageProperties(properties: Record<string, any> = {}): Promise<Record<string, any>> {
    const event = await eventFactory.generatePageEvent(
      properties.category,
      properties.name,
      properties
    );

    return event.properties || {};
  }

  /**
   * Helper to get the event context populated by EventFactory.generatePageEvent
   */
  async function getPageContext(properties: Record<string, any> = {}): Promise<Record<string, any>> {
    const event = await eventFactory.generatePageEvent(
      properties.category,
      properties.name,
      properties
    );

    return (event.context as Record<string, any>) || {};
  }

  describe("Basic URL parsing", () => {
    it("should extract url, path, hash, and query from a complete URL", async () => {
      setMockLocation("https://formo.so/blog/guide?foo=bar#intro");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/blog/guide?foo=bar#intro");
      expect(props.path).to.equal("/blog/guide");
      expect(props.hash).to.equal("#intro");
      expect(props.query).to.equal("foo=bar");
    });

    it("should handle URL without query parameters", async () => {
      setMockLocation("https://formo.so/blog#section");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/blog#section");
      expect(props.path).to.equal("/blog");
      expect(props.hash).to.equal("#section");
      expect(props.query).to.equal("");
    });

    it("should handle URL without hash", async () => {
      setMockLocation("https://formo.so/blog?foo=bar");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/blog?foo=bar");
      expect(props.path).to.equal("/blog");
      expect(props.hash).to.equal("");
      expect(props.query).to.equal("foo=bar");
    });

    it("should handle URL without query or hash", async () => {
      setMockLocation("https://formo.so/blog");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/blog");
      expect(props.path).to.equal("/blog");
      expect(props.hash).to.equal("");
      expect(props.query).to.equal("");
    });

    it("should handle root path URL", async () => {
      setMockLocation("https://formo.so/");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/");
      expect(props.path).to.equal("/");
      expect(props.hash).to.equal("");
      expect(props.query).to.equal("");
    });

    it("should strip trailing slashes from non-root page URL and path", async () => {
      setMockLocation("https://formo.so/limit/bnb/?foo=bar#intro");

      const props = await getPageProperties();
      const context = await getPageContext();

      expect(props.url).to.equal("https://formo.so/limit/bnb?foo=bar#intro");
      expect(props.path).to.equal("/limit/bnb");
      expect(props.hash).to.equal("#intro");
      expect(props.query).to.equal("foo=bar");
      expect(context.page_url).to.equal(
        "https://formo.so/limit/bnb?foo=bar#intro"
      );
    });

    it("should preserve the root slash when normalizing page URL and path", async () => {
      setMockLocation("https://formo.so/?foo=bar#intro");

      const props = await getPageProperties();
      const context = await getPageContext();

      expect(props.url).to.equal("https://formo.so/?foo=bar#intro");
      expect(props.path).to.equal("/");
      expect(context.page_url).to.equal("https://formo.so/?foo=bar#intro");
    });
  });

  describe("Query parameter parsing", () => {
    it("should parse individual query parameters as properties", async () => {
      setMockLocation("https://formo.so/blog?foo=bar&baz=qux");

      const props = await getPageProperties();

      expect(props.query).to.equal("foo=bar&baz=qux");
      expect(props.foo).to.equal("bar");
      expect(props.baz).to.equal("qux");
    });

    it("should parse multiple query parameters with special characters", async () => {
      setMockLocation("https://formo.so/blog?param1=value%201&param2=value%202");

      const props = await getPageProperties();

      expect(props.param1).to.equal("value 1");
      expect(props.param2).to.equal("value 2");
    });

    it("should handle query parameters with numeric values", async () => {
      setMockLocation("https://formo.so/blog?page=2&limit=50");

      const props = await getPageProperties();

      expect(props.page).to.equal("2");
      expect(props.limit).to.equal("50");
    });

    it("should handle query parameters with empty values", async () => {
      setMockLocation("https://formo.so/blog?foo=&bar=value");

      const props = await getPageProperties();

      expect(props.foo).to.equal("");
      expect(props.bar).to.equal("value");
    });

    it("should handle duplicate query parameters (takes first value)", async () => {
      setMockLocation("https://formo.so/blog?foo=first&foo=second");

      const props = await getPageProperties();

      expect(props.foo).to.equal("first");
    });
  });

  describe("Context field exclusion", () => {
    it("should exclude UTM parameters from properties", async () => {
      setMockLocation("https://formo.so/blog?utm_source=twitter&utm_medium=social&custom=value");

      const props = await getPageProperties();

      // UTM parameters should NOT be in properties
      expect(props.utm_source).to.be.undefined;
      expect(props.utm_medium).to.be.undefined;

      // Custom parameter should be in properties
      expect(props.custom).to.equal("value");

      // Full query string should still be present
      expect(props.query).to.equal("utm_source=twitter&utm_medium=social&custom=value");
    });

    it("should exclude all UTM parameters", async () => {
      setMockLocation(
        "https://formo.so/blog?utm_source=google&utm_medium=cpc&utm_campaign=summer&utm_term=analytics&utm_content=banner"
      );

      const props = await getPageProperties();

      expect(props.utm_source).to.be.undefined;
      expect(props.utm_medium).to.be.undefined;
      expect(props.utm_campaign).to.be.undefined;
      expect(props.utm_term).to.be.undefined;
      expect(props.utm_content).to.be.undefined;
    });

    it("should exclude referral parameters", async () => {
      setMockLocation("https://formo.so/blog?ref=abc123&referral=partner&refcode=xyz&af=aff1");

      const props = await getPageProperties();

      expect(props.ref).to.be.undefined;
      expect(props.referral).to.be.undefined;
      expect(props.refcode).to.be.undefined;
      expect(props.af).to.be.undefined;
    });

    it("should exclude referrer parameter", async () => {
      setMockLocation("https://formo.so/blog?referrer=external");

      const props = await getPageProperties();

      expect(props.referrer).to.be.undefined;
    });

    it("should include non-context query parameters", async () => {
      setMockLocation("https://formo.so/blog?utm_source=twitter&foo=bar&custom_param=value");

      const props = await getPageProperties();

      expect(props.utm_source).to.be.undefined;
      expect(props.foo).to.equal("bar");
      expect(props.custom_param).to.equal("value");
    });
  });

  describe("Semantic property protection", () => {
    it("should not allow query parameters to override category", async () => {
      setMockLocation("https://formo.so/blog?category=malicious");

      const props = await getPageProperties({ category: "blog" });

      expect(props.category).to.equal("blog");
    });

    it("should not allow query parameters to override name", async () => {
      setMockLocation("https://formo.so/blog?name=malicious");

      const props = await getPageProperties({ name: "Analytics Guide" });

      expect(props.name).to.equal("Analytics Guide");
    });

    it("should not allow query parameters to override url", async () => {
      setMockLocation("https://formo.so/blog?url=https://malicious.com");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so/blog?url=https://malicious.com");
      expect(props.url).to.not.equal("https://malicious.com");
    });

    it("should not allow query parameters to override path", async () => {
      setMockLocation("https://formo.so/blog?path=/malicious");

      const props = await getPageProperties();

      expect(props.path).to.equal("/blog");
      expect(props.path).to.not.equal("/malicious");
    });

    it("should not allow query parameters to override hash", async () => {
      setMockLocation("https://formo.so/blog?hash=malicious#intro");

      const props = await getPageProperties();

      expect(props.hash).to.equal("#intro");
    });

    it("should not allow query parameters to override query", async () => {
      setMockLocation("https://formo.so/blog?query=malicious&foo=bar");

      const props = await getPageProperties();

      expect(props.query).to.equal("query=malicious&foo=bar");
      expect(props.query).to.not.equal("malicious");
    });

    it("should prevent undefined category/name from being set by query params", async () => {
      setMockLocation("https://formo.so/blog?category=hack&name=test");

      // Simulate page event generation where category/name might be undefined
      const props = await getPageProperties({ category: undefined, name: undefined });

      // These should remain undefined, not be set by query params
      expect(props.category).to.be.undefined;
      expect(props.name).to.be.undefined;
    });
  });

  describe("Property override behavior", () => {
    it("should not override existing properties", async () => {
      setMockLocation("https://formo.so/blog?foo=from-url");

      const props = await getPageProperties({ foo: "existing-value" });

      expect(props.foo).to.equal("existing-value");
    });

    it("should only add new properties from query params", async () => {
      setMockLocation("https://formo.so/blog?new_param=new_value&existing=url_value");

      const props = await getPageProperties({ existing: "original" });

      expect(props.new_param).to.equal("new_value");
      expect(props.existing).to.equal("original");
    });
  });

  describe("Hash/fragment handling", () => {
    it("should include the # prefix in hash property", async () => {
      setMockLocation("https://formo.so/blog#section");

      const props = await getPageProperties();

      expect(props.hash).to.equal("#section");
      expect(props.hash).to.include("#");
    });

    it("should handle empty hash correctly", async () => {
      setMockLocation("https://formo.so/blog");

      const props = await getPageProperties();

      expect(props.hash).to.equal("");
    });

    it("should handle hash with special characters", async () => {
      setMockLocation("https://formo.so/blog#section-1.2");

      const props = await getPageProperties();

      expect(props.hash).to.equal("#section-1.2");
    });

    it("should preserve hash with encoded characters", async () => {
      setMockLocation("https://formo.so/blog#section%20with%20spaces");

      const props = await getPageProperties();

      expect(props.hash).to.equal("#section%20with%20spaces");
    });
  });

  describe("Edge cases", () => {
    it("should handle complex URLs with all components", async () => {
      setMockLocation(
        "https://formo.so/blog/analytics/guide?utm_source=twitter&foo=bar&custom=value#introduction"
      );

      const props = await getPageProperties({ category: "guides", name: "Web3 Analytics" });

      expect(props.url).to.equal(
        "https://formo.so/blog/analytics/guide?utm_source=twitter&foo=bar&custom=value#introduction"
      );
      expect(props.path).to.equal("/blog/analytics/guide");
      expect(props.hash).to.equal("#introduction");
      expect(props.query).to.equal("utm_source=twitter&foo=bar&custom=value");
      expect(props.category).to.equal("guides");
      expect(props.name).to.equal("Web3 Analytics");
      expect(props.utm_source).to.be.undefined; // Excluded
      expect(props.foo).to.equal("bar"); // Included
      expect(props.custom).to.equal("value"); // Included
    });

    it("should handle query parameters with boolean-like values", async () => {
      setMockLocation("https://formo.so/blog?debug=true&verbose=false");

      const props = await getPageProperties();

      expect(props.debug).to.equal("true");
      expect(props.verbose).to.equal("false");
    });

    it("should handle URLs with port numbers", async () => {
      setMockLocation("https://formo.so:8080/blog?foo=bar#section");

      const props = await getPageProperties();

      expect(props.url).to.equal("https://formo.so:8080/blog?foo=bar#section");
      expect(props.path).to.equal("/blog");
    });

    it("should handle localhost URLs", async () => {
      setMockLocation("http://localhost:3000/test?param=value#top");

      const props = await getPageProperties();

      expect(props.url).to.equal("http://localhost:3000/test?param=value#top");
      expect(props.path).to.equal("/test");
      expect(props.query).to.equal("param=value");
      expect(props.hash).to.equal("#top");
      expect(props.param).to.equal("value");
    });

    it("should handle deeply nested paths", async () => {
      setMockLocation("https://formo.so/a/b/c/d/e/f?param=value");

      const props = await getPageProperties();

      expect(props.path).to.equal("/a/b/c/d/e/f");
    });

    it("should handle mixed case query parameter names", async () => {
      setMockLocation("https://formo.so/blog?FooBar=value&ALLCAPS=test");

      const props = await getPageProperties();

      // EventFactory converts all properties to snake_case
      expect(props.foo_bar).to.equal("value");
      expect(props.allcaps).to.equal("test");
    });
  });

  describe("Backward compatibility", () => {
    it("should maintain hash format with # prefix for backward compatibility", async () => {
      setMockLocation("https://formo.so/blog#intro");

      const props = await getPageProperties();

      // Hash should include # for backward compatibility
      expect(props.hash).to.equal("#intro");
      expect(props.hash.charAt(0)).to.equal("#");
    });

    it("should not break existing URL construction patterns", async () => {
      setMockLocation("https://formo.so/blog#section");

      const props = await getPageProperties();

      // Should be able to reconstruct URL with hash
      const reconstructed = props.url;
      expect(reconstructed).to.include(props.hash);
    });
  });

  describe("Security considerations", () => {
    it("should prevent XSS attempts via query parameters", async () => {
      setMockLocation("https://formo.so/blog?<script>alert('xss')</script>=value");

      const props = await getPageProperties();

      // The parameter name itself contains the script tag, but it should be treated as a string
      expect(Object.keys(props)).to.include("<script>alert('xss')</script>");
    });

    it("should handle SQL injection-like patterns in query params", async () => {
      setMockLocation("https://formo.so/blog?id=1';DROP TABLE users;--");

      const props = await getPageProperties();

      expect(props.id).to.equal("1';DROP TABLE users;--");
    });

    it("should protect against category/name injection attempts", async () => {
      setMockLocation("https://formo.so/blog?category=<script>alert('xss')</script>");

      const props = await getPageProperties({ category: "legitimate" });

      expect(props.category).to.equal("legitimate");
      expect(props.category).to.not.include("script");
    });
  });

  describe("Properties object mutation", () => {
    it("should not mutate the original properties object", async () => {
      setMockLocation("https://formo.so/blog?foo=bar#intro");

      const originalProps = { category: "test", custom: "value" };
      const originalPropsCopy = { ...originalProps };

      await getPageProperties(originalProps);

      // Original object should be unchanged
      expect(originalProps).to.deep.equal(originalPropsCopy);
      expect((originalProps as any).url).to.be.undefined;
      expect((originalProps as any).path).to.be.undefined;
      expect((originalProps as any).hash).to.be.undefined;
      expect((originalProps as any).query).to.be.undefined;
      expect((originalProps as any).foo).to.be.undefined;
    });

    it("should allow reusing properties object across multiple calls", async () => {
      const reusableProps = { category: "page_view" };

      // First call with one URL
      setMockLocation("https://formo.so/page1?param1=value1");
      const props1 = await getPageProperties(reusableProps);

      expect(props1.path).to.equal("/page1");
      expect(props1.param1).to.equal("value1");

      // Second call with different URL - should get new values
      setMockLocation("https://formo.so/page2?param2=value2");
      const props2 = await getPageProperties(reusableProps);

      expect(props2.path).to.equal("/page2");
      expect(props2.param2).to.equal("value2");
      // Should not have param1 from first call
      expect((props2 as any).param1).to.be.undefined;
    });
  });

  describe("Click ID parameters (sticky across session)", () => {
    // The StorageManager is a singleton that persists across tests and retains
    // traffic-source entries from earlier tests. Clear that key before each test
    // so persistence behaviour can be asserted cleanly.
    beforeEach(() => {
      try {
        session().remove(SESSION_TRAFFIC_SOURCE_KEY);
      } catch {}
    });

    it("should capture click IDs into context on the landing pageview", async () => {
      setMockLocation("https://formo.so/?gclid=test123&fbclid=fb456");

      const context = await getPageContext();

      expect(context.gclid).to.equal("test123");
      expect(context.fbclid).to.equal("fb456");
    });

    it("should exclude click IDs from page properties", async () => {
      setMockLocation("https://formo.so/?gclid=test123&fbclid=fb456&custom=keep");

      const props = await getPageProperties();

      expect(props.gclid).to.be.undefined;
      expect(props.fbclid).to.be.undefined;
      // Non-click-ID query params still pass through
      expect(props.custom).to.equal("keep");
    });

    it("should persist click IDs across subsequent pageviews in the same session", async () => {
      // Landing page writes gclid to sessionStorage via the traffic-source key.
      setMockLocation("https://formo.so/?gclid=test123");
      const landingContext = await getPageContext();
      expect(landingContext.gclid).to.equal("test123");

      // Second page in the same session: URL has no gclid, so the value must
      // come from the stored traffic-source blob.
      setMockLocation("https://formo.so/dashboard");
      const secondContext = await getPageContext();
      expect(secondContext.gclid).to.equal("test123");
    });

    it("should not leak click IDs into a fresh session", async () => {
      // Landing page has the click ID, which gets written to sessionStorage
      setMockLocation("https://formo.so/?gclid=test123");
      await getPageContext();

      // Simulate a brand new session (new tab): sessionStorage is empty
      session().remove(SESSION_TRAFFIC_SOURCE_KEY);

      setMockLocation("https://formo.so/dashboard");
      const freshContext = await getPageContext();
      expect(freshContext.gclid).to.equal("");
    });

    it("should let a newer click ID override the stored value", async () => {
      setMockLocation("https://formo.so/?gclid=old");
      const firstContext = await getPageContext();
      expect(firstContext.gclid).to.equal("old");

      setMockLocation("https://formo.so/landing?gclid=new");
      const secondContext = await getPageContext();
      expect(secondContext.gclid).to.equal("new");
    });

    it("should capture each supported click ID vendor param", async () => {
      setMockLocation(
        "https://formo.so/?gclid=g1&gad_source=g2&fbclid=f1&msclkid=m1&twclid=t2&li_fat_id=l1&rdt_cid=r1&ttclid=t1"
      );

      const context = await getPageContext();

      expect(context.gclid).to.equal("g1");
      expect(context.gad_source).to.equal("g2");
      expect(context.fbclid).to.equal("f1");
      expect(context.msclkid).to.equal("m1");
      expect(context.twclid).to.equal("t2");
      expect(context.li_fat_id).to.equal("l1");
      expect(context.rdt_cid).to.equal("r1");
      expect(context.ttclid).to.equal("t1");
    });

    it("should default missing click IDs to empty string", async () => {
      setMockLocation("https://formo.so/?gclid=only");

      const context = await getPageContext();

      expect(context.gclid).to.equal("only");
      expect(context.fbclid).to.equal("");
      expect(context.msclkid).to.equal("");
      expect(context.rdt_cid).to.equal("");
    });

    it("should not capture unknown attribution-like params as click IDs", async () => {
      setMockLocation("https://formo.so/?random_clid=abc");

      const context = await getPageContext();

      expect(context.random_clid).to.be.undefined;
    });
  });

  describe("Referrer (sticky across session)", () => {
    // Clear stored traffic-source state between tests so each scenario starts
    // from a clean session.
    beforeEach(() => {
      try {
        session().remove(SESSION_TRAFFIC_SOURCE_KEY);
      } catch {}
    });

    it("should capture document.referrer into context on the landing pageview", async () => {
      setMockLocation("https://formo.so/", "https://google.com/");

      const context = await getPageContext();

      expect(context.referrer).to.equal("https://google.com/");
    });

    it("should persist the entry referrer across internal navigation", async () => {
      // Landing: external referrer is captured and stored.
      setMockLocation("https://formo.so/", "https://google.com/");
      const landingContext = await getPageContext();
      expect(landingContext.referrer).to.equal("https://google.com/");

      // Internal navigation: browser sets document.referrer to the previous
      // same-domain page. The sticky stored value must win so attribution
      // continues to reflect the session's true source.
      setMockLocation("https://formo.so/dashboard", "https://formo.so/");
      const secondContext = await getPageContext();
      expect(secondContext.referrer).to.equal("https://google.com/");
    });

    it("should not overwrite a stored referrer when a different external referrer appears mid-session", async () => {
      setMockLocation("https://formo.so/", "https://google.com/");
      await getPageContext();

      // User clicks an outbound link and comes back via a different referrer.
      // First-touch attribution wins.
      setMockLocation("https://formo.so/landing", "https://facebook.com/");
      const secondContext = await getPageContext();
      expect(secondContext.referrer).to.equal("https://google.com/");
    });

    it("should fall back to document.referrer when no stored referrer exists", async () => {
      // Fresh session with no stored value yet: context wins via the OR fallback.
      setMockLocation("https://formo.so/landing", "https://twitter.com/");

      const context = await getPageContext();

      expect(context.referrer).to.equal("https://twitter.com/");
    });

    it("should not leak referrer into a fresh session", async () => {
      // Landing pageview writes referrer to sessionStorage.
      setMockLocation("https://formo.so/", "https://google.com/");
      await getPageContext();

      // Simulate a brand new session (new tab): sessionStorage is empty.
      session().remove(SESSION_TRAFFIC_SOURCE_KEY);

      // Direct landing with no referrer in the new session.
      setMockLocation("https://formo.so/dashboard");
      const freshContext = await getPageContext();
      expect(freshContext.referrer).to.equal("");
    });

    it("should not capture internal navigation as referrer after a direct landing", async () => {
      // Direct landing: no referrer, nothing stored.
      setMockLocation("https://formo.so/");
      const landingContext = await getPageContext();
      expect(landingContext.referrer).to.equal("");

      // Internal nav: browser sets document.referrer to the previous same-host
      // page. This must NOT be treated as the session's entry referrer.
      setMockLocation("https://formo.so/dashboard", "https://formo.so/");
      const secondContext = await getPageContext();
      expect(secondContext.referrer).to.equal("");

      // A subsequent internal hop must also stay empty — i.e. the previous
      // same-host URL did not sneak into sessionStorage on the prior event.
      setMockLocation("https://formo.so/pricing", "https://formo.so/dashboard");
      const thirdContext = await getPageContext();
      expect(thirdContext.referrer).to.equal("");
    });

    it("should treat a different host as external even when paths look similar", async () => {
      // Sanity: cross-host nav is still captured (we filter on hostname, not
      // arbitrary URL substrings).
      setMockLocation("https://formo.so/", "https://app.formo.so/");
      const context = await getPageContext();
      expect(context.referrer).to.equal("https://app.formo.so/");
    });
  });

  describe("Referral code parameter (default query params)", () => {
    // `ref` is sticky across the session, so clear the stored traffic source
    // before each test to assert per-URL extraction cleanly.
    beforeEach(() => {
      try {
        session().remove(SESSION_TRAFFIC_SOURCE_KEY);
      } catch {}
    });

    const cases: Array<[string, string]> = [
      ["ref", "abc123"],
      ["referral", "partner"],
      ["refcode", "xyz789"],
      ["af", "aff42"],
      ["referrer", "ambassador"],
    ];

    cases.forEach(([param, code]) => {
      it(`should capture ?${param}=CODE into context.ref`, async () => {
        setMockLocation(`https://formo.so/?${param}=${code}`);

        const context = await getPageContext();

        expect(context.ref).to.equal(code);
      });
    });

    it("should keep the ?referrer referral code separate from document.referrer", async () => {
      // ?referrer is a referral code (context.ref); document.referrer is the
      // external entry URL (context.referrer). They must not be conflated.
      setMockLocation("https://formo.so/?referrer=ambassador", "https://google.com/");

      const context = await getPageContext();

      expect(context.ref).to.equal("ambassador");
      expect(context.referrer).to.equal("https://google.com/");
    });

    it("should resolve referral params in default order (earlier param wins)", async () => {
      setMockLocation("https://formo.so/?af=aff42&referrer=ambassador&ref=abc123");

      const context = await getPageContext();

      // `ref` precedes `af` and `referrer` in the default list.
      expect(context.ref).to.equal("abc123");
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import { EventFactory } from "../../../src/event/EventFactory";
import { initStorageManager, session } from "../../../src/storage";
import { SESSION_TRAFFIC_SOURCE_KEY } from "../../../src/constants";

/**
 * Tests for sensitive query-parameter exclusion in page properties.
 *
 * Two layers:
 * - A built-in always-on denylist (privy_oauth_code, privy_oauth_state) that is
 *   stripped regardless of configuration and cannot be disabled.
 * - An opt-in `tracking.excludeQueryParams` array of key names
 *   (case-insensitive).
 *
 * Only the query string is redacted — the URL hash/fragment is intentionally
 * left untouched. Excluded params must not appear in `url`, `query`, or the
 * per-parameter page-property explosion.
 */
describe("EventFactory query parameter exclusion", () => {
  let jsdom: JSDOM;

  beforeEach(() => {
    jsdom = new JSDOM(
      "<!DOCTYPE html><html><head><title>Test Page</title></head><body></body></html>",
      { url: "https://formo.so/" }
    );

    Object.defineProperty(global, "window", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "document", {
      value: jsdom.window.document, writable: true, configurable: true,
    });
    Object.defineProperty(global, "location", {
      value: jsdom.window.location, writable: true, configurable: true,
    });
    Object.defineProperty(global, "globalThis", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "navigator", {
      value: jsdom.window.navigator, writable: true, configurable: true,
    });
    Object.defineProperty(global, "screen", {
      value: jsdom.window.screen, writable: true, configurable: true,
    });
    Object.defineProperty(global, "devicePixelRatio", {
      value: 1, writable: true, configurable: true,
    });
    Object.defineProperty(global, "innerWidth", {
      value: 1920, writable: true, configurable: true,
    });
    Object.defineProperty(global, "innerHeight", {
      value: 1080, writable: true, configurable: true,
    });
    Object.defineProperty(global, "Intl", {
      value: {
        DateTimeFormat: () => ({
          resolvedOptions: () => ({ timeZone: "America/New_York" }),
        }),
      },
      writable: true, configurable: true,
    });
    Object.defineProperty(global, "localStorage", {
      value: jsdom.window.localStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "sessionStorage", {
      value: jsdom.window.sessionStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "crypto", {
      value: { randomUUID: () => "12345678-1234-1234-1234-123456789abc" },
      writable: true, configurable: true,
    });

    initStorageManager("test-write-key");

    // Clear sticky traffic-source state so each test starts clean.
    try {
      session().remove(SESSION_TRAFFIC_SOURCE_KEY);
    } catch {}
  });

  afterEach(() => {
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).location;
    delete (global as any).globalThis;
    delete (global as any).navigator;
    delete (global as any).screen;
    delete (global as any).devicePixelRatio;
    delete (global as any).innerWidth;
    delete (global as any).innerHeight;
    delete (global as any).Intl;
    delete (global as any).localStorage;
    delete (global as any).sessionStorage;
    delete (global as any).crypto;
    if (jsdom) jsdom.window.close();
  });

  function setMockLocation(url: string, referrer?: string) {
    if (jsdom) jsdom.window.close();
    jsdom = new JSDOM(
      "<!DOCTYPE html><html><head><title>Test Page</title></head><body></body></html>",
      referrer ? { url, referrer } : { url }
    );
    (global as any).window = jsdom.window;
    (global as any).document = jsdom.window.document;
    (global as any).location = jsdom.window.location;
    (global as any).globalThis = jsdom.window;
  }

  async function getEvent(
    factory: EventFactory,
    properties: Record<string, any> = {}
  ): Promise<Record<string, any>> {
    return (await factory.generatePageEvent(
      properties.category,
      properties.name,
      properties
    )) as unknown as Record<string, any>;
  }

  async function getProps(
    factory: EventFactory,
    properties: Record<string, any> = {}
  ): Promise<Record<string, any>> {
    const event = await getEvent(factory, properties);
    return (event.properties as Record<string, any>) || {};
  }

  describe("built-in always-on denylist", () => {
    it("always strips Privy OAuth params with no configuration", async () => {
      setMockLocation(
        "https://formo.so/callback?privy_oauth_code=SECRET_CODE&privy_oauth_state=CSRF_TOKEN&privy_oauth_provider=google&foo=bar"
      );
      const props = await getProps(new EventFactory());

      expect(props.url).to.not.contain("SECRET_CODE");
      expect(props.url).to.not.contain("CSRF_TOKEN");
      expect(props.url).to.not.contain("privy_oauth_provider");
      expect(props.query).to.equal("foo=bar");
      expect(props.privy_oauth_code).to.be.undefined;
      expect(props.privy_oauth_state).to.be.undefined;
      expect(props.privy_oauth_provider).to.be.undefined;
      expect(props.foo).to.equal("bar");
    });

    it("matches built-in params case-insensitively", async () => {
      setMockLocation("https://formo.so/callback?PRIVY_OAUTH_CODE=SECRET_CODE&keep=1");
      const props = await getProps(new EventFactory());

      expect(props.url).to.not.contain("SECRET_CODE");
      expect(props.keep).to.equal("1");
    });

    it("leaves the URL hash/fragment untouched", async () => {
      setMockLocation(
        "https://formo.so/callback?privy_oauth_code=SECRET_CODE#privy_oauth_state=HASH_KEPT"
      );
      const props = await getProps(new EventFactory());

      expect(props.url).to.not.contain("SECRET_CODE");
      expect(props.url).to.contain("#privy_oauth_state=HASH_KEPT");
      expect(props.hash).to.equal("#privy_oauth_state=HASH_KEPT");
      expect(props.query).to.equal("");
    });
  });

  describe("excludeQueryParams as an array", () => {
    it("strips configured keys on top of the built-in defaults", async () => {
      setMockLocation(
        "https://formo.so/page?token=ABC&privy_oauth_code=SECRET_CODE&page=2"
      );
      const props = await getProps(
        new EventFactory({ tracking: { excludeQueryParams: ["token"] } })
      );

      expect(props.url).to.not.contain("ABC");
      expect(props.url).to.not.contain("SECRET_CODE");
      expect(props.token).to.be.undefined;
      expect(props.privy_oauth_code).to.be.undefined;
      expect(props.page).to.equal("2");
    });

    it("matches configured keys case-insensitively", async () => {
      setMockLocation("https://formo.so/page?Token=ABC&keep=1");
      const props = await getProps(
        new EventFactory({ tracking: { excludeQueryParams: ["token"] } })
      );

      expect(props.url).to.not.contain("ABC");
      expect(props.keep).to.equal("1");
    });
  });

  // Excluded params must not leak through the event *context* either — not via
  // page_url, not via the referrer, and not via the traffic-source extraction
  // (utm_*, click ids, ref), which parses the URL separately from page props.
  describe("event context redaction", () => {
    it("strips excluded params from context.page_url", async () => {
      setMockLocation(
        "https://formo.so/page?token=ABC&privy_oauth_code=SECRET&keep=1"
      );
      const event = await getEvent(
        new EventFactory({ tracking: { excludeQueryParams: ["token"] } })
      );

      expect(event.context.page_url).to.not.contain("ABC");
      expect(event.context.page_url).to.not.contain("SECRET");
      expect(event.context.page_url).to.contain("keep=1");
    });

    it("does not leak an excluded param that is also a traffic-source key", async () => {
      setMockLocation(
        "https://formo.so/page?utm_source=secretcampaign&gclid=SECRETCLICK&ref=SECRETREF&utm_medium=email"
      );
      const event = await getEvent(
        new EventFactory({
          tracking: { excludeQueryParams: ["utm_source", "gclid", "ref"] },
        })
      );

      // Excluded traffic-source keys are emptied in context...
      expect(event.context.utm_source).to.equal("");
      expect(event.context.gclid).to.equal("");
      expect(event.context.ref).to.equal("");
      // ...while non-excluded traffic-source keys still capture normally.
      expect(event.context.utm_medium).to.equal("email");
    });

    it("strips excluded params from the external referrer", async () => {
      setMockLocation(
        "https://formo.so/page?keep=1",
        "https://referrer.example/landing?token=SECRETTOKEN&campaign=spring"
      );
      const event = await getEvent(
        new EventFactory({ tracking: { excludeQueryParams: ["token"] } })
      );

      expect(event.context.referrer).to.not.contain("SECRETTOKEN");
      expect(event.context.referrer).to.contain("campaign=spring");
    });

    it("strips the always-on privy defaults from the external referrer", async () => {
      setMockLocation(
        "https://formo.so/page?keep=1",
        "https://referrer.example/oauth?privy_oauth_code=SECRETCODE&ok=1"
      );
      const event = await getEvent(new EventFactory());

      expect(event.context.referrer).to.not.contain("SECRETCODE");
      expect(event.context.referrer).to.contain("ok=1");
    });

    it("drops a sticky traffic-source value stored under an earlier, looser config", async () => {
      // First pageview: no exclusion, so gclid is captured and persisted to the
      // sticky SESSION_TRAFFIC_SOURCE_KEY store.
      setMockLocation("https://formo.so/page?gclid=OLDCLICK");
      const first = await getEvent(new EventFactory());
      expect(first.context.gclid).to.equal("OLDCLICK");

      // Later pageview on a clean URL, now excluding gclid. The stored value
      // must not resurface in context from session storage.
      setMockLocation("https://formo.so/page?keep=1");
      const second = await getEvent(
        new EventFactory({ tracking: { excludeQueryParams: ["gclid"] } })
      );
      expect(second.context.gclid).to.equal("");
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import { EventFactory } from "../../../src/event/EventFactory";
import {
  sanitizeClickId,
  sanitizeRef,
  sanitizeUtm,
  sanitizeTrafficSources,
} from "../../../src/event/sanitize";
import { initStorageManager, session } from "../../../src/storage";
import { SESSION_TRAFFIC_SOURCE_KEY } from "../../../src/constants";

/**
 * Tests for traffic-source value sanitization.
 *
 * Vulnerability scanners crawl customer sites injecting XSS probes into every
 * query parameter; without validation those payloads were captured verbatim
 * as utm_* / click-id / ref values and polluted attribution reporting. The
 * payloads asserted below are real values observed in production events.
 */

// Acunetix DOM-XSS probe — injected into every query param of scanned sites.
const ACUNETIX_PAYLOAD = `javascript:domxssExecutionSink(1,"'\\"><xsstag>()locxss")`;

describe("traffic-source sanitizers", () => {
  describe("sanitizeClickId", () => {
    it("keeps legitimate platform click IDs", () => {
      // Real-shaped values: gclid (base64url), fbclid (with _aem_ segment),
      // twclid, gad_source.
      const legit = [
        "CjwKCAjw6c63BhAiEiwAF0EH1PGgnZ8bZBz-M9EbXCzC1XPeIcbEHKMYXBLmM0Wxrr0y7DEjuMt5RoCP34QAvD_BwE",
        "IwZXh0bgNhZW0CMTEAAR1x_aem_N1o_0GyGQNu376L7Pt6VcA",
        "26cq47zg1e7en9nn2n7dj0y7n1",
        "1",
        "a.b-c_d",
      ];
      for (const v of legit) {
        expect(sanitizeClickId(v)).to.equal(v);
      }
    });

    it("drops the Acunetix DOM-XSS probe", () => {
      expect(sanitizeClickId(ACUNETIX_PAYLOAD)).to.equal("");
    });

    it("drops values with a URL-encoded fragment glued on", () => {
      // Observed: fbclid followed by %23open-positions from a mangled link.
      expect(
        sanitizeClickId("PAQ0xDSwOS0eZleHRuA_aem_x%23open-positions")
      ).to.equal("");
    });

    it("drops values over 255 characters", () => {
      expect(sanitizeClickId("a".repeat(256))).to.equal("");
      expect(sanitizeClickId("a".repeat(255))).to.equal("a".repeat(255));
    });

    it("returns empty for empty input", () => {
      expect(sanitizeClickId("")).to.equal("");
    });

    it("drops values with embedded whitespace", () => {
      expect(sanitizeClickId("abc def")).to.equal("");
      expect(sanitizeClickId("abc\tdef")).to.equal("");
    });
  });

  describe("sanitizeRef", () => {
    it("keeps legitimate referral codes", () => {
      const legit = ["D7WXN_N4", "ILPYAL", "nb4wtgm", "ref.code-01", "0xAbC123"];
      for (const v of legit) {
        expect(sanitizeRef(v)).to.equal(v);
      }
    });

    it("drops scanner and malformed values observed in production", () => {
      const garbage = [
        "javascript:alert(1)",
        // Referral code with a full URL glued on.
        "D7WXN_N4https://divvy.bet/world-cup-2026?ref=D7WXN_N4",
        // Referral code glued to a path.
        "ILPYAL/contact",
        // Trailing mangled-encoding characters.
        "solanaIDñ",
        "niphermed…",
        "081544cf62b49b3cd68c374ac4689db3⁠�",
        // Trailing punctuation / whitespace.
        "nb4wtgm?",
        "-MCW_JQR -",
        "83a5886c901e030991ad4ec5936a84fa\\",
        // Free text typed into the ref param.
        "PROPR (currently in closed public phase)",
      ];
      for (const v of garbage) {
        expect(sanitizeRef(v), v).to.equal("");
      }
    });

    it("caps length at 64 characters", () => {
      expect(sanitizeRef("a".repeat(64))).to.equal("a".repeat(64));
      expect(sanitizeRef("a".repeat(65))).to.equal("");
    });

    it("returns empty for empty input", () => {
      expect(sanitizeRef("")).to.equal("");
    });

    it("drops non-ASCII referral codes", () => {
      // The strict token allowlist is intentional: no legitimate production
      // ref uses characters outside [A-Za-z0-9._-].
      expect(sanitizeRef("код")).to.equal("");
      expect(sanitizeRef("REF•CODE")).to.equal("");
    });
  });

  describe("sanitizeUtm", () => {
    it("keeps free-form but benign UTM values", () => {
      const legit = [
        "twitter",
        "summer_sale-2026",
        "spring sale + more",
        "newsletter+june",
        "キャンペーン", // unicode campaign name
        "100%_off",
      ];
      for (const v of legit) {
        expect(sanitizeUtm(v)).to.equal(v);
      }
    });

    it("drops XSS probes observed in production", () => {
      const garbage = [
        ACUNETIX_PAYLOAD,
        "<script>alert(1234)</script>",
        "<img src=x onerror=alert('injected!')>",
        `"><input type="hidden" oncontentvisibilityautostatechange="confirm(/Bypassed/)" style="content-visibility:auto">`,
        `'><marquee onstart="[cookie].find(confirm)"`,
        "/\">'><sVg/onxxx=\"x=y\"oNload=1^(alert)(1)``^1//",
        "#/<script>alert(1234)</script>",
      ];
      for (const v of garbage) {
        expect(sanitizeUtm(v), v).to.equal("");
      }
    });

    it("drops dangerous scheme prefixes case-insensitively", () => {
      expect(sanitizeUtm("JavaScript:alert(1)")).to.equal("");
      expect(sanitizeUtm(" data:text/html;base64,x")).to.equal("");
      expect(sanitizeUtm("vbscript:msgbox(1)")).to.equal("");
      // A scheme-ish word not in a scheme position is fine.
      expect(sanitizeUtm("my-javascript-course")).to.equal(
        "my-javascript-course"
      );
    });

    it("drops control, zero-width, and replacement characters", () => {
      expect(sanitizeUtm("camp\u0000aign")).to.equal("");
      expect(sanitizeUtm("camp\taign")).to.equal("");
      expect(sanitizeUtm("camp\naign")).to.equal("");
      expect(sanitizeUtm("camp\u200baign")).to.equal("");
      expect(sanitizeUtm("camp\u202eaign")).to.equal(""); // RTL override
      expect(sanitizeUtm("campaign\ufeff")).to.equal(""); // BOM
      expect(sanitizeUtm("campaign\ufffd")).to.equal("");
    });

    it("returns empty for empty input", () => {
      expect(sanitizeUtm("")).to.equal("");
    });

    it("drops values over 255 characters", () => {
      expect(sanitizeUtm("a".repeat(255))).to.equal("a".repeat(255));
      expect(sanitizeUtm("a".repeat(256))).to.equal("");
    });
  });

  describe("sanitizeTrafficSources", () => {
    it("applies the per-field rules and leaves referrer untouched", () => {
      const result = sanitizeTrafficSources({
        utm_source: "<script>alert(1)</script>",
        utm_campaign: "summer sale",
        twclid: ACUNETIX_PAYLOAD,
        gclid: "CjwKCAjw_legit-id",
        ref: "javascript:alert(1)",
        referrer: "https://t.co/abc?x='quoted'",
      });
      expect(result.utm_source).to.equal("");
      expect(result.utm_campaign).to.equal("summer sale");
      expect(result.twclid).to.equal("");
      expect(result.gclid).to.equal("CjwKCAjw_legit-id");
      expect(result.ref).to.equal("");
