import { describe, it } from "mocha";
import { expect } from "chai";
import { parsePrivyProperties, PrivyUser } from "../../src/privy";
// Internal: not part of the public API, reached publicly via identify(user).
import { identifyPrivyUser } from "../../src/privy/utils";
import type { IFormoAnalytics } from "../../src/types";

interface RecordedIdentify {
  params: {
    address: string;
    userId?: string;
    setActive?: boolean;
    rdns?: string;
    providerName?: string;
  };
  properties?: Record<string, unknown>;
}

/** The address of the wallet promoted to active (setActive:true), if any. */
function activeAddressOf(calls: RecordedIdentify[]): string | undefined {
  return calls.find((c) => c.params.setActive === true)?.params.address;
}

/**
 * Minimal IFormoAnalytics stub that records identify() calls so we can assert
 * ordering, attribution flags, and forwarded per-wallet metadata.
 */
function makeRecorder(): { analytics: IFormoAnalytics; calls: RecordedIdentify[] } {
  const calls: RecordedIdentify[] = [];
  const analytics = {
    identify: async (params: any, properties: any) => {
      calls.push({ params, properties });
    },
  } as unknown as IFormoAnalytics;
  return { analytics, calls };
}

const EMBEDDED = "0x1111111111111111111111111111111111111111";
const EXTERNAL = "0x2222222222222222222222222222222222222222";
const EXTERNAL_2 = "0x3333333333333333333333333333333333333333";

describe("Privy Utilities", () => {
  describe("parsePrivyProperties", () => {
    describe("properties extraction", () => {
      it("should extract core identifiers", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          createdAt: new Date(1699900000000),
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.privyDid).to.equal("did:privy:abc123");
        expect(properties.privyCreatedAt).to.equal(1699900000000);
      });

      it("should extract email from user.email", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          email: { address: "user@example.com" },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.email).to.equal("user@example.com");
      });

      it("should extract social account usernames", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          twitter: { subject: "tw1", username: "twitteruser", name: null, profilePictureUrl: null },
          discord: { subject: "dc1", username: "discorduser#1234", email: null },
          github: { subject: "gh1", username: "ghuser", name: null },
          farcaster: { fid: 12345, ownerAddress: "0x0", username: "fname", displayName: null, bio: null, pfp: null },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.twitter).to.equal("twitteruser");
        expect(properties.discord).to.equal("discorduser#1234");
        expect(properties.github).to.equal("ghuser");
        expect(properties.farcaster).to.equal("fname");
        // farcasterFid should NOT be included
        expect(properties).to.not.have.property("farcasterFid");
      });

      it("should extract social account emails", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          google: { subject: "g1", email: "user@gmail.com", name: null },
          apple: { subject: "a1", email: "user@icloud.com" },
          linkedin: { subject: "li1", email: "user@company.com", name: null, vanityName: null },
          spotify: { subject: "sp1", email: "user@spotify.com", name: null },
          line: { subject: "ln1", email: "user@line.me", name: null },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.google).to.equal("user@gmail.com");
        expect(properties.apple).to.equal("user@icloud.com");
        expect(properties.linkedin).to.equal("user@company.com");
        expect(properties.spotify).to.equal("user@spotify.com");
        expect(properties.line).to.equal("user@line.me");
      });

      it("should fall back to google email if email is blank", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          google: { subject: "g1", email: "user@gmail.com", name: null },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.email).to.equal("user@gmail.com");
      });

      it("should fall back to apple email if email and google are blank", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          apple: { subject: "a1", email: "user@icloud.com" },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.email).to.equal("user@icloud.com");
      });

      it("should fall back to linkedin email if email, google, and apple are blank", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedin: { subject: "li1", email: "user@company.com", name: null, vanityName: null },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.email).to.equal("user@company.com");
      });

      it("should prefer direct email over OAuth fallback", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          email: { address: "direct@example.com" },
          google: { subject: "g1", email: "user@gmail.com", name: null },
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.email).to.equal("direct@example.com");
      });

      it("should extract from linkedAccounts as fallback", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            { type: "twitter_oauth", username: "twitteruser" },
            { type: "github_oauth", username: "ghuser" },
            { type: "farcaster", username: "fname" },
          ],
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.twitter).to.equal("twitteruser");
        expect(properties.github).to.equal("ghuser");
        expect(properties.farcaster).to.equal("fname");
      });

      it("should use farcaster displayName as fallback if username is missing", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            { type: "farcaster", displayName: "Farcaster User" },
          ],
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.farcaster).to.equal("Farcaster User");
      });

      it("should handle user with no linked accounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
        };

        const { properties } = parsePrivyProperties(user);

        expect(properties.privyDid).to.equal("did:privy:abc123");
        expect(properties.email).to.be.undefined;
        expect(properties.twitter).to.be.undefined;
      });

      it("should accept every form createdAt arrives in", () => {
        // The React SDK gives a Date, but a user from the REST API or a JSON
        // round-trip carries a string or number. Calling .getTime() on those
        // throws, and identify()'s outer catch would swallow it - so the whole
        // one-liner would silently emit nothing.
        const expected = 1699900000000;

        expect(
          parsePrivyProperties({
            id: "did:privy:abc123",
            createdAt: new Date(expected),
          }).properties.privyCreatedAt
        ).to.equal(expected);

        expect(
          parsePrivyProperties({
            id: "did:privy:abc123",
            createdAt: new Date(expected).toISOString(),
          }).properties.privyCreatedAt
        ).to.equal(expected);

        // Epoch milliseconds pass through; REST-style seconds are scaled up.
        expect(
          parsePrivyProperties({ id: "did:privy:abc123", createdAt: expected })
            .properties.privyCreatedAt
        ).to.equal(expected);
        expect(
          parsePrivyProperties({
            id: "did:privy:abc123",
            createdAt: expected / 1000,
          }).properties.privyCreatedAt
        ).to.equal(expected);
      });

      it("should not throw or emit NaN for an unusable createdAt", () => {
        for (const createdAt of [
          "not a date",
          new Date("nonsense"),
          NaN,
          null as unknown as undefined,
        ]) {
          const { properties } = parsePrivyProperties({
            id: "did:privy:abc123",
            createdAt: createdAt as never,
          });
          expect(properties.privyCreatedAt).to.be.undefined;
        }
      });

      it("should extract phone from user.phone", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          phone: { number: "+15551234567" },
        };

        expect(parsePrivyProperties(user).properties.phone).to.equal(
          "+15551234567"
        );
      });

      it("should extract phone from a linked phone account (number, not address)", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [{ type: "phone", number: "+15559876543" }],
        };

        expect(parsePrivyProperties(user).properties.phone).to.equal(
          "+15559876543"
        );
      });

      it("should extract twitch from the accessor and from linkedAccounts", () => {
        expect(
          parsePrivyProperties({
            id: "did:privy:abc123",
            twitch: { subject: "s", username: "streamer" },
          }).properties.twitch
        ).to.equal("streamer");

        expect(
          parsePrivyProperties({
            id: "did:privy:abc123",
            linkedAccounts: [
              { type: "twitch_oauth", username: "streamer2" },
            ],
          }).properties.twitch
        ).to.equal("streamer2");
      });

      it("should extract customUserId from a custom_auth account", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [{ type: "custom_auth", customUserId: "app-user-42" }],
        };

        expect(parsePrivyProperties(user).properties.customUserId).to.equal(
          "app-user-42"
        );
      });

      it("should not derive account-set summary properties", () => {
        // Counts and type lists are intentionally NOT sent: they are derivable
        // server-side from the per-wallet identifies, and because they would be
        // shared across every wallet, any link/unlink would change them for all
        // wallets and re-emit each one.
        const { properties } = parsePrivyProperties({
          id: "did:privy:abc123",
          linkedAccounts: [
            { type: "wallet", address: EXTERNAL },
            { type: "passkey", credentialId: "cred-1" },
          ],
        });

        expect(properties.privyLinkedAccounts).to.be.undefined;
        expect(properties.privyLinkedAccountCount).to.be.undefined;
        expect(properties.privyWalletCount).to.be.undefined;
        expect(properties.privyHasPasskey).to.be.undefined;
      });
    });

    describe("wallets extraction", () => {
      it("should extract wallet addresses from linkedAccounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
              walletClientType: "metamask",
              chainType: "ethereum",
            },
            {
              type: "wallet",
              address: "0x2222222222222222222222222222222222222222",
              walletClientType: "privy",
              chainType: "ethereum",
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(2);
        expect(wallets[0].address).to.equal("0x1111111111111111111111111111111111111111");
        expect(wallets[0].walletClient).to.equal("metamask");
        expect(wallets[0].isEmbedded).to.be.false;
        expect(wallets[1].address).to.equal("0x2222222222222222222222222222222222222222");
        expect(wallets[1].walletClient).to.equal("privy");
        expect(wallets[1].isEmbedded).to.be.true;
      });

      it("should identify Privy embedded wallets", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
              walletClientType: "privy",
            },
            {
              type: "wallet",
              address: "0x2222222222222222222222222222222222222222",
              walletClient: "privy", // alternative field name
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets[0].isEmbedded).to.be.true;
        expect(wallets[1].isEmbedded).to.be.true;
      });

      it("should filter out non-wallet accounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
            },
            { type: "email", address: "user@example.com" },
            { type: "google_oauth", email: "user@gmail.com" },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(1);
        expect(wallets[0].address).to.equal("0x1111111111111111111111111111111111111111");
      });

      it("should extract smart wallet accounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
              walletClientType: "metamask",
            },
            {
              type: "smart_wallet",
              address: "0x3333333333333333333333333333333333333333",
              walletClientType: "privy",
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(2);
        expect(wallets[0].address).to.equal("0x1111111111111111111111111111111111111111");
        expect(wallets[1].address).to.equal("0x3333333333333333333333333333333333333333");
        expect(wallets[1].isEmbedded).to.be.true;
      });

      it("should filter out wallets without addresses", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
            },
            {
              type: "wallet",
              // no address
              walletClientType: "metamask",
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(1);
      });

      it("should return empty array for user with no linked accounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.deep.equal([]);
      });

      it("should return empty array for user with no wallet accounts", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            { type: "email", address: "user@example.com" },
            { type: "google_oauth", email: "user@gmail.com" },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.deep.equal([]);
      });

      it("should extract cross_app embedded and smart wallets", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "cross_app",
              subject: "provider-subject",
              embeddedWallets: [{ address: EMBEDDED }],
              smartWallets: [{ address: EXTERNAL_2, chainType: "ethereum" }],
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(2);
        expect(wallets.map((w) => w.address)).to.deep.equal([
          EMBEDDED,
          EXTERNAL_2,
        ]);
        expect(wallets.every((w) => w.isEmbedded)).to.equal(true);
        expect(wallets[0].walletClient).to.equal("cross_app");
        expect(wallets[1].chainType).to.equal("ethereum");
      });

      it("should prefer the richer wallet entry regardless of account order", () => {
        // A cross_app entry carries only an address, so it defaults to
        // cross_app/embedded. When the same address also appears as a real
        // wallet account, the real one must win even if Privy listed the
        // cross_app account first - otherwise metadata (and the last-external
        // active-wallet fallback, which keys on isEmbedded) depends on ordering.
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "cross_app",
              subject: "provider-subject",
              embeddedWallets: [{ address: EXTERNAL }],
            },
            {
              type: "wallet",
              address: EXTERNAL,
              walletClientType: "metamask",
              chainType: "ethereum",
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(1);
        expect(wallets[0].walletClient).to.equal("metamask");
        expect(wallets[0].chainType).to.equal("ethereum");
        expect(wallets[0].isEmbedded).to.equal(false);
      });

      it("should deduplicate an address linked as both wallet and smart_wallet", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
            // Same address, different casing - EVM addresses are case-insensitive.
            { type: "smart_wallet", address: EXTERNAL.toUpperCase().replace("0X", "0x") },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets).to.have.length(1);
        // The first occurrence wins, so the richer `wallet` entry is kept.
        expect(wallets[0].walletClient).to.equal("metamask");
      });

      it("should include chainType when available", () => {
        const user: PrivyUser = {
          id: "did:privy:abc123",
          linkedAccounts: [
            {
              type: "wallet",
              address: "0x1111111111111111111111111111111111111111",
              chainType: "ethereum",
            },
            {
              type: "wallet",
              address: "0x2222222222222222222222222222222222222222",
              chainType: "solana",
            },
          ],
        };

        const { wallets } = parsePrivyProperties(user);

        expect(wallets[0].chainType).to.equal("ethereum");
        expect(wallets[1].chainType).to.equal("solana");
      });
    });
  });

  describe("identifyPrivyUser", () => {
    it("identifies every linked wallet tagged with the Privy DID", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        email: { address: "user@example.com" },
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask", chainType: "ethereum" },
          { type: "wallet", address: EMBEDDED, walletClientType: "privy", chainType: "ethereum" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      expect(calls).to.have.length(2);
      for (const call of calls) {
        expect(call.params.userId).to.equal("did:privy:abc123");
      }
    });

    it("forwards per-wallet metadata and shared profile properties", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        email: { address: "user@example.com" },
        linkedAccounts: [
          { type: "wallet", address: EMBEDDED, walletClientType: "privy", chainType: "ethereum" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      expect(calls).to.have.length(1);
      const props = calls[0].properties!;
      // per-wallet metadata
      expect(props.wallet_client).to.equal("privy");
      expect(props.chain_type).to.equal("ethereum");
      expect(props.is_embedded).to.equal(true);
      // shared profile properties
      expect(props.privyDid).to.equal("did:privy:abc123");
      expect(props.email).to.equal("user@example.com");
    });

    it("omits wallet_client/chain_type when absent but always sends is_embedded", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [{ type: "wallet", address: EXTERNAL }],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      const props = calls[0].properties!;
      expect(props).to.not.have.property("wallet_client");
      expect(props).to.not.have.property("chain_type");
      expect(props.is_embedded).to.equal(false);
    });

    it("promotes the provided active wallet (setActive) and records the rest for clustering", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
          { type: "wallet", address: EXTERNAL_2, walletClientType: "rainbow" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user, { activeAddress: EXTERNAL });

      // Every wallet is identified for clustering...
      expect(calls.map((c) => c.params.address)).to.have.members([
        EMBEDDED,
        EXTERNAL,
        EXTERNAL_2,
      ]);
      // ...but only the active wallet is promoted to attribution.
      expect(activeAddressOf(calls)).to.equal(EXTERNAL);
      for (const c of calls) {
        expect(c.params.setActive).to.equal(c.params.address === EXTERNAL);
      }
    });

    it("matches the active wallet case-insensitively (EVM)", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user, {
        activeAddress: EMBEDDED.toUpperCase(),
      });

      expect(activeAddressOf(calls)).to.equal(EMBEDDED);
    });

    it("falls back to the last external wallet when no active address or user.wallet", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      // Heuristic: embedded wallets deprioritized, so the external wallet is active.
      expect(activeAddressOf(calls)).to.equal(EXTERNAL);
    });

    it("defaults the active wallet to user.wallet when activeAddress is omitted", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        // Privy's surfaced primary wallet is the embedded one.
        wallet: { address: EMBEDDED },
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      // user.wallet (EMBEDDED) is promoted, overriding the external-wallet heuristic.
      expect(activeAddressOf(calls)).to.equal(EMBEDDED);
    });

    it("lets an explicit activeAddress override user.wallet", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        wallet: { address: EMBEDDED },
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user, { activeAddress: EXTERNAL });

      expect(activeAddressOf(calls)).to.equal(EXTERNAL);
    });

    it("compares Solana active addresses case-sensitively (no false match)", async () => {
      // A Base58 Solana address (case-sensitive), lower-cased into a variant
      // that is NOT the same address.
      const SOL = "So11111111111111111111111111111111111111112";
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: SOL, walletClientType: "privy", chainType: "solana" },
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask", chainType: "ethereum" },
        ],
      };

      // Wrong-case Solana address is explicitly provided but doesn't match, so
      // no wallet is promoted (an explicit address is matched strictly, never
      // guessed) - while both wallets are still recorded for clustering.
      const miss = makeRecorder();
      await identifyPrivyUser(miss.analytics, user, {
        activeAddress: SOL.toLowerCase(),
      });
      expect(activeAddressOf(miss.calls)).to.equal(undefined);
      expect(miss.calls).to.have.length(2);

      // Exact-case Solana address IS accepted → promoted.
      const hit = makeRecorder();
      await identifyPrivyUser(hit.analytics, user, { activeAddress: SOL });
      expect(activeAddressOf(hit.calls)).to.equal(SOL);
    });

    it("merges options.properties into every identify call", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: EMBEDDED, walletClientType: "privy" },
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
        ],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user, {
        properties: { plan: "pro" },
      });

      expect(calls).to.have.length(2);
      for (const call of calls) {
        expect(call.properties!.plan).to.equal("pro");
      }
    });

    it("does nothing when the user has no linked wallets", async () => {
      const user: PrivyUser = {
        id: "did:privy:abc123",
        email: { address: "user@example.com" },
        linkedAccounts: [{ type: "email", address: "user@example.com" }],
      };
      const { analytics, calls } = makeRecorder();

      await identifyPrivyUser(analytics, user);

      expect(calls).to.have.length(0);
    });

    it("emits nothing and does not reconcile chain when tracking is suppressed", async () => {
      const calls: RecordedIdentify[] = [];
      let chainReconciled = false;
      const analytics = {
        identify: async (params: any, properties: any) => {
          calls.push({ params, properties });
        },
        syncPrivyActiveChain: () => {
          chainReconciled = true;
        },
        isTrackingSuppressed: () => true,
      } as unknown as IFormoAnalytics;

      const user: PrivyUser = {
        id: "did:privy:abc123",
        linkedAccounts: [
          { type: "wallet", address: EXTERNAL, walletClientType: "metamask" },
        ],
      };

      const result = await identifyPrivyUser(analytics, user);

      // No identifies emitted, and - critically - no chain reconciliation, which
      // would otherwise clear an excluded chain id while no identify runs.
      expect(calls).to.have.length(0);
      expect(chainReconciled).to.equal(false);
      expect(result).to.equal(undefined);
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import { JSDOM } from "jsdom";
import {
  FormoAnalyticsSession,
  SESSION_WALLET_IDENTIFIED_KEY,
} from "../../src/session";
import { cookie, initStorageManager } from "../../src/storage";

/**
 * Session identify deduplication with a user ID folded into the key.
 *
 * Verifies that attaching a user ID (e.g. a Privy DID) to an already-identified
 * wallet is treated as a new identity and re-emits, while repeated identifies
 * with the same (address, rdns, userId) are still deduped.
 */
describe("Session identify dedup with userId", () => {
  let jsdom: JSDOM;

  const ADDRESS = "0x1111111111111111111111111111111111111111";
  const RDNS = "io.metamask";
  const DID = "did:privy:abc123";

  beforeEach(() => {
    jsdom = new JSDOM("<!DOCTYPE html><html><head></head><body></body></html>", {
      url: "https://example.com",
    });
    Object.defineProperty(global, "window", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "document", {
      value: jsdom.window.document, writable: true, configurable: true,
    });
    Object.defineProperty(global, "navigator", {
      value: jsdom.window.navigator, writable: true, configurable: true,
    });
    initStorageManager("test-write-key");
  });

  afterEach(() => {
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).navigator;
  });

  it("re-emits when a userId is attached to an already-identified wallet", () => {
    const session = new FormoAnalyticsSession();

    // First identify: anonymous (no userId).
    expect(session.isWalletIdentified(ADDRESS, RDNS)).to.equal(false);
    session.markWalletIdentified(ADDRESS, RDNS);
    expect(session.isWalletIdentified(ADDRESS, RDNS)).to.equal(true);

    // Same wallet, now with a Privy DID: must NOT be considered already
    // identified, so a fresh identify event is emitted.
    expect(session.isWalletIdentified(ADDRESS, RDNS, DID)).to.equal(false);
    session.markWalletIdentified(ADDRESS, RDNS, DID);
    expect(session.isWalletIdentified(ADDRESS, RDNS, DID)).to.equal(true);
  });

  it("dedups repeated identifies with the same address + userId", () => {
    const session = new FormoAnalyticsSession();

    expect(session.isWalletIdentified(ADDRESS, "", DID)).to.equal(false);
    session.markWalletIdentified(ADDRESS, "", DID);
    // A second identify with the same userId is a duplicate.
    expect(session.isWalletIdentified(ADDRESS, "", DID)).to.equal(true);
  });

  it("treats different userIds on the same wallet as distinct identities", () => {
    const session = new FormoAnalyticsSession();
    const otherDid = "did:privy:xyz789";

    session.markWalletIdentified(ADDRESS, "", DID);
    expect(session.isWalletIdentified(ADDRESS, "", DID)).to.equal(true);
    // Switching to a different user on the same wallet re-emits.
    expect(session.isWalletIdentified(ADDRESS, "", otherDid)).to.equal(false);
  });

  it("handles userIds containing a comma (the cookie delimiter) without breaking dedup", () => {
    const session = new FormoAnalyticsSession();
    // An external userId that contains the comma used to join cookie entries.
    const commaUser = "external,user,42";

    expect(session.isWalletIdentified(ADDRESS, "", commaUser)).to.equal(false);
    session.markWalletIdentified(ADDRESS, "", commaUser);
    // Encoded before storage, so the raw comma can't corrupt the key: the same
    // (wallet, user) is now recognized as already identified rather than
    // re-emitting on every call.
    expect(session.isWalletIdentified(ADDRESS, "", commaUser)).to.equal(true);
  });

  it("retains every identity for a many-wallet user (size-bounded, not a 20-entry cap)", () => {
    const session = new FormoAnalyticsSession();
    const did = "did:privy:manywallets";
    const addrs = Array.from(
      { length: 40 },
      (_, i) => "0x" + (i + 1).toString(16).padStart(40, "0")
    );

    for (const a of addrs) session.markWalletIdentified(a, "", did);

    // All 40 remain recognized - well past the old fixed 20-entry limit, which
    // would have evicted the first 20 and re-emitted them on a later sync.
    for (const a of addrs) {
      expect(session.isWalletIdentified(a, "", did)).to.equal(true);
    }
  });

  it("does not collide a userId with a provider RDNS of the same value", () => {
    const session = new FormoAnalyticsSession();
    // Anonymous identify with rdns = "io.metamask".
    session.markWalletIdentified(ADDRESS, "io.metamask");
    expect(session.isWalletIdentified(ADDRESS, "io.metamask")).to.equal(true);
    // A later identify whose userId equals that RDNS string is a distinct tuple
    // (address + empty rdns + userId), so it must NOT be considered already
    // identified - its identity-link event still emits.
    expect(session.isWalletIdentified(ADDRESS, "", "io.metamask")).to.equal(false);
  });

  it("stays backward compatible: omitting userId matches legacy keys", () => {
    const session = new FormoAnalyticsSession();

    // Legacy call path (address + rdns, no userId) is unchanged.
    session.markWalletIdentified(ADDRESS, RDNS);
    expect(session.isWalletIdentified(ADDRESS, RDNS)).to.equal(true);
    // address-only fallback (no rdns, no userId) is also unchanged.
    session.markWalletIdentified(ADDRESS, "");
    expect(session.isWalletIdentified(ADDRESS, "")).to.equal(true);
  });

  describe("properties fingerprint in the dedup key", () => {
    it("re-emits when the properties change for the same wallet + userId", () => {
      const session = new FormoAnalyticsSession();
      const before = { privyDid: DID, email: "a@b.com" };
      // The motivating case: the user links a Google account. Same wallet,
      // same DID - only the properties changed.
      const after = { privyDid: DID, email: "a@b.com", google: "a@b.com" };

      session.markWalletIdentified(ADDRESS, RDNS, DID, before);
      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, before)).to.equal(
        true
      );

      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, after)).to.equal(
        false
      );
    });

    it("dedups a repeat with identical properties", () => {
      const session = new FormoAnalyticsSession();
      const properties = { privyDid: DID, email: "a@b.com", is_embedded: false };

      session.markWalletIdentified(ADDRESS, RDNS, DID, properties);

      // A re-render passing an equal (but not identical) object must not
      // re-emit, or every React render would produce an identify event.
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          privyDid: DID,
          email: "a@b.com",
          is_embedded: false,
        })
      ).to.equal(true);
    });

    it("is insensitive to property key order", () => {
      const session = new FormoAnalyticsSession();

      session.markWalletIdentified(ADDRESS, RDNS, DID, {
        email: "a@b.com",
        privyDid: DID,
      });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          privyDid: DID,
          email: "a@b.com",
        })
      ).to.equal(true);
    });

    it("distinguishes nested and array property changes", () => {
      const session = new FormoAnalyticsSession();

      session.markWalletIdentified(ADDRESS, RDNS, DID, {
        meta: { plan: "free", tags: ["a", "b"] },
      });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          meta: { plan: "pro", tags: ["a", "b"] },
        })
      ).to.equal(false);
      // Array order is meaningful, unlike object key order.
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          meta: { plan: "free", tags: ["b", "a"] },
        })
      ).to.equal(false);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          meta: { plan: "free", tags: ["a", "b"] },
        })
      ).to.equal(true);
    });

    it("treats empty properties as no properties (legacy key shape)", () => {
      const session = new FormoAnalyticsSession();

      // An identify with no properties must keep matching a key stored by the
      // pre-hash SDK, so upgrading doesn't re-emit every plain identify.
      session.markWalletIdentified(ADDRESS, RDNS, DID);
      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, {})).to.equal(true);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, undefined)
      ).to.equal(true);
    });

    it("never throws on values JSON.stringify rejects", () => {
      const session = new FormoAnalyticsSession();

      // A web3 app can easily pass a BigInt balance or an object with a back
      // reference. Hashing runs AFTER identify() has updated the active
      // address/user, so a throw here would leave mutated identity state and
      // emit nothing.
      const circular: Record<string, unknown> = { name: "wallet" };
      circular.self = circular;

      // Built at runtime, not as a `10n` literal: this project targets ES5,
      // where BigInt literals aren't available to the compiler.
      const bigIntValue = (global as any).BigInt(10);

      const awkward = {
        balance: bigIntValue,
        circular,
        fn: () => undefined,
        sym: Symbol("s"),
        invalidDate: new Date("nonsense"),
        nan: NaN,
        infinite: Infinity,
        set: new Set([1, 2]),
        map: new Map([["k", "v"]]),
      };

      expect(() =>
        session.markWalletIdentified(ADDRESS, RDNS, DID, awkward)
      ).to.not.throw();
      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, awkward)).to.equal(
        true
      );
    });

    it("distinguishes a BigInt change and a repeated object reference", () => {
      const session = new FormoAnalyticsSession();

      const big = (global as any).BigInt;
      session.markWalletIdentified(ADDRESS, RDNS, DID, { balance: big(10) });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, { balance: big(11) })
      ).to.equal(false);

      // The same object used twice in one payload is not a cycle, so both
      // occurrences must serialize identically rather than one becoming
      // "circular".
      const shared = { plan: "pro" };
      session.markWalletIdentified(ADDRESS, RDNS, DID, {
        a: shared,
        b: shared,
      });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          a: { plan: "pro" },
          b: { plan: "pro" },
        })
      ).to.equal(true);
    });

    it("re-emits when a profile reverts to an earlier state", () => {
      const session = new FormoAnalyticsSession();
      const withoutGoogle = { privyDid: DID, email: "a@b.com" };
      const withGoogle = { privyDid: DID, email: "a@b.com", google: "a@b.com" };

      // Link Google, then unlink it. Dedup means "same as this wallet's LAST
      // identify", not "seen at any point", so the revert must re-emit -
      // otherwise unlinking would silently produce no event.
      session.markWalletIdentified(ADDRESS, RDNS, DID, withoutGoogle);
      session.markWalletIdentified(ADDRESS, RDNS, DID, withGoogle);

      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, withoutGoogle)
      ).to.equal(false);
      // ...and the current state still dedupes.
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, withGoogle)
      ).to.equal(true);
    });

    it("keeps one entry per wallet-user instead of one per profile state", () => {
      const session = new FormoAnalyticsSession();

      // Five profile changes must not leave five keys behind, or a many-wallet
      // user would push the cookie into size-based eviction.
      for (let i = 0; i < 5; i++) {
        session.markWalletIdentified(ADDRESS, RDNS, DID, { step: i });
      }

      const stored = cookie().get(SESSION_WALLET_IDENTIFIED_KEY) ?? "";
      const keys = stored.split(",").filter(Boolean);

      expect(keys).to.have.length(1);
      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, { step: 4 })).to.equal(
        true
      );
      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, { step: 0 })).to.equal(
        false
      );
    });

    it("supersedes only the same wallet-user, not other identities", () => {
      const session = new FormoAnalyticsSession();
      const OTHER_DID = "did:privy:other";

      session.markWalletIdentified(ADDRESS, RDNS, DID, { v: 1 });
      session.markWalletIdentified(ADDRESS, RDNS, OTHER_DID, { v: 1 });
      // A legacy anonymous key for the same wallet must also survive.
      session.markWalletIdentified(ADDRESS, RDNS);

      session.markWalletIdentified(ADDRESS, RDNS, DID, { v: 2 });

      expect(session.isWalletIdentified(ADDRESS, RDNS, DID, { v: 2 })).to.equal(true);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, OTHER_DID, { v: 1 })
      ).to.equal(true);
      expect(session.isWalletIdentified(ADDRESS, RDNS)).to.equal(true);
    });

    it("honors toJSON() so wire-distinct values are distinct keys", () => {
      const session = new FormoAnalyticsSession();

      // URL has no enumerable own keys - without honoring toJSON() both of
      // these canonicalize to "{}" and the changed URL is falsely deduped.
      session.markWalletIdentified(ADDRESS, RDNS, DID, {
        endpoint: new URL("https://a.example/"),
      });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          endpoint: new URL("https://b.example/"),
        })
      ).to.equal(false);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          endpoint: new URL("https://a.example/"),
        })
      ).to.equal(true);
    });

    it("does not throw when reading properties throws", () => {
      const session = new FormoAnalyticsSession();

      // A Proxy whose ownKeys trap throws escapes a naive Object.keys() call
      // made outside the fingerprint guard.
      const hostile = new Proxy(
        {},
        {
          ownKeys() {
            throw new Error("hostile ownKeys");
          },
        }
      ) as Record<string, unknown>;

      expect(() =>
        session.markWalletIdentified(ADDRESS, RDNS, DID, hostile)
      ).to.not.throw();
      expect(() =>
        session.isWalletIdentified(ADDRESS, RDNS, DID, hostile)
      ).to.not.throw();
    });

    it("dedupes payloads that serialize identically on the wire", () => {
      const session = new FormoAnalyticsSession();

      // JSON omits undefined/function/symbol properties, so all of these send
      // the exact same bytes. Fingerprinting them differently would emit a
      // second identify carrying a byte-identical payload.
      session.markWalletIdentified(ADDRESS, RDNS, DID, { a: 1 });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, {
          a: 1,
          b: undefined,
          c: () => undefined,
          d: Symbol("s"),
        })
      ).to.equal(true);

      // NaN and Infinity are both sent as null.
      session.markWalletIdentified(ADDRESS, RDNS, DID, { n: null });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, { n: NaN })
      ).to.equal(true);
    });

    it("treats an all-omitted property bag as no properties", () => {
      const session = new FormoAnalyticsSession();

      // Sends `{}`, exactly like passing nothing, so it must keep the legacy
      // key shape rather than minting a distinct hashed key.
      session.markWalletIdentified(ADDRESS, RDNS, DID);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, { a: undefined })
      ).to.equal(true);
    });

    it("keeps the stored cookie within the browser's size limit", () => {
      const session = new FormoAnalyticsSession();

      // Keys are percent-encoded once when built and again by CookieStorage,
      // so a raw-length budget understates what is written. Overflowing makes
      // the browser reject the write, so nothing persists and every identify
      // re-emits for the rest of the session.
      for (let i = 0; i < 200; i++) {
        session.markWalletIdentified(
          `0x${i.toString(16).padStart(40, "0")}`,
          RDNS,
          // A DID-shaped id, whose colons percent-encode twice.
          `did:privy:cm3np${i}`,
          { privyDid: `did:privy:cm3np${i}`, email: "user@example.com" }
        );
      }

      const stored = cookie().get(SESSION_WALLET_IDENTIFIED_KEY) ?? "";
      expect(encodeURIComponent(stored).length).to.be.at.most(4096 - 512);
      // Eviction must never drop the key it just wrote.
      expect(
        session.isWalletIdentified(
          `0x${(199).toString(16).padStart(40, "0")}`,
          RDNS,
          "did:privy:cm3np199",
          { privyDid: "did:privy:cm3np199", email: "user@example.com" }
        )
      ).to.equal(true);
    });

    it("treats undefined and null property values as different", () => {
      const session = new FormoAnalyticsSession();

      // JSON omits an undefined property but sends null, so collapsing the two
      // would suppress a real value -> null update.
      session.markWalletIdentified(ADDRESS, RDNS, DID, { plan: undefined });
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, DID, { plan: null })
      ).to.equal(false);
    });

    it("keys properties without a userId, without colliding on rdns", () => {
      const session = new FormoAnalyticsSession();
      const properties = { plan: "pro" };

      session.markWalletIdentified(ADDRESS, RDNS, undefined, properties);
      expect(
        session.isWalletIdentified(ADDRESS, RDNS, undefined, properties)
      ).to.equal(true);
      // The legacy 2-component `address:rdns` key must stay distinct from the
      // 4-component keyed-with-properties form.
      expect(session.isWalletIdentified(ADDRESS, RDNS)).to.equal(false);
    });
  });
});

import { describe, it } from "mocha";
import { expect } from "chai";
import {
  SESSION_WALLET_DETECTED_KEY,
  SESSION_WALLET_IDENTIFIED_KEY,
} from "../../src/session";

/**
 * Tests to ensure session cookie key values remain stable for backward compatibility.
 *
 * IMPORTANT: These keys are stored in user browsers as cookies. If these values change,
 * existing users will have their session state reset, causing:
 * - Duplicate wallet detection events
 * - Duplicate wallet identification events
 * - Poor analytics data quality
 *
 * If you need to change these values, you MUST implement a migration strategy.
 */
describe("Session Constants - Backward Compatibility", () => {
  describe("Cookie key values must not change", () => {
    it("SESSION_WALLET_DETECTED_KEY should have stable value", () => {
      // This value is stored in user browsers - DO NOT CHANGE without migration
      expect(SESSION_WALLET_DETECTED_KEY).to.equal("wallet-detected");
    });

    it("SESSION_WALLET_IDENTIFIED_KEY should have stable value", () => {
      // This value is stored in user browsers - DO NOT CHANGE without migration
      expect(SESSION_WALLET_IDENTIFIED_KEY).to.equal("wallet-identified");
    });
  });
});

import { expect } from "chai";
import { describe, it } from "mocha";
import {
  isSolanaAddress,
  getValidSolanaAddress,
  isBlockedSolanaAddress,
  publicKeyToAddress,
  areSolanaAddressesEqual,
  SOLANA_SYSTEM_ADDRESSES,
} from "../../src/solana/address";
import { SolanaPublicKey } from "../../src/solana/types";

describe("Solana Address Utilities", () => {
  describe("isSolanaAddress", () => {
    it("should return true for a valid Solana address (typical wallet)", () => {
      // Example Solana mainnet wallet address
      expect(isSolanaAddress("FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn")).to.be
        .true;
    });

    it("should return true for a valid Solana address (32 chars minimum)", () => {
      expect(isSolanaAddress("11111111111111111111111111111111")).to.be.true;
    });

    it("should return true for a valid Solana address (44 chars maximum)", () => {
      expect(
        isSolanaAddress("TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA")
      ).to.be.true;
    });

    it("should return false for addresses that are too short", () => {
      expect(isSolanaAddress("FDKJvWcJNe6wecbg")).to.be.false;
    });

    it("should return false for addresses that are too long", () => {
      expect(
        isSolanaAddress(
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4TnFDKJvWcJNe6wecbg"
        )
      ).to.be.false;
    });

    it("should return false for invalid Base58 characters (0, O, I, l)", () => {
      // These characters are not in Base58
      expect(isSolanaAddress("0DKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfW")).to.be.false;
      expect(isSolanaAddress("ODKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfW")).to.be.false;
      expect(isSolanaAddress("IDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfW")).to.be.false;
      expect(isSolanaAddress("lDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfW")).to.be.false;
    });

    it("should return false for non-string values", () => {
      expect(isSolanaAddress(null)).to.be.false;
      expect(isSolanaAddress(undefined)).to.be.false;
      expect(isSolanaAddress(123)).to.be.false;
      expect(isSolanaAddress({})).to.be.false;
      expect(isSolanaAddress([])).to.be.false;
    });

    it("should return false for empty strings", () => {
      expect(isSolanaAddress("")).to.be.false;
      expect(isSolanaAddress("   ")).to.be.false;
    });

    it("should handle addresses with leading/trailing whitespace", () => {
      expect(
        isSolanaAddress("  FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn  ")
      ).to.be.true;
    });

    it("should return false for Ethereum addresses (hex format)", () => {
      expect(isSolanaAddress("0xa5cc3c03994DB5b0d9A5eEdD10CabaB0813678AC")).to.be
        .false;
    });
  });

  describe("getValidSolanaAddress", () => {
    it("should return trimmed address for valid addresses", () => {
      const result = getValidSolanaAddress(
        "  FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn  "
      );
      expect(result).to.equal("FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn");
    });

    it("should return null for invalid addresses", () => {
      expect(getValidSolanaAddress("invalid")).to.be.null;
      expect(getValidSolanaAddress("")).to.be.null;
      expect(getValidSolanaAddress(null)).to.be.null;
      expect(getValidSolanaAddress(undefined)).to.be.null;
    });

    it("should handle PublicKey objects", () => {
      const mockPublicKey: SolanaPublicKey = {
        toBase58: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toString: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toBytes: () => new Uint8Array(32),
        equals: () => false,
      };

      const result = getValidSolanaAddress(mockPublicKey);
      expect(result).to.equal("FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn");
    });

    it("should return null for PublicKey that throws", () => {
      const mockPublicKey: SolanaPublicKey = {
        toBase58: () => {
          throw new Error("Invalid key");
        },
        toString: () => "",
        toBytes: () => new Uint8Array(32),
        equals: () => false,
      };

      const result = getValidSolanaAddress(mockPublicKey);
      expect(result).to.be.null;
    });
  });

  describe("isBlockedSolanaAddress", () => {
    it("should return true for system program address", () => {
      expect(isBlockedSolanaAddress(SOLANA_SYSTEM_ADDRESSES.SYSTEM_PROGRAM)).to
        .be.true;
    });

    it("should return true for token program address", () => {
      expect(isBlockedSolanaAddress(SOLANA_SYSTEM_ADDRESSES.TOKEN_PROGRAM)).to.be
        .true;
    });

    it("should return false for normal wallet addresses", () => {
      expect(
        isBlockedSolanaAddress("FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn")
      ).to.be.false;
    });

    it("should return false for invalid addresses", () => {
      expect(isBlockedSolanaAddress("invalid")).to.be.false;
      expect(isBlockedSolanaAddress(null)).to.be.false;
      expect(isBlockedSolanaAddress(undefined)).to.be.false;
    });
  });

  describe("publicKeyToAddress", () => {
    it("should convert valid PublicKey to address string", () => {
      const mockPublicKey: SolanaPublicKey = {
        toBase58: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toString: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toBytes: () => new Uint8Array(32),
        equals: () => false,
      };

      expect(publicKeyToAddress(mockPublicKey)).to.equal(
        "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn"
      );
    });

    it("should return null for null publicKey", () => {
      expect(publicKeyToAddress(null)).to.be.null;
    });

    it("should return null for undefined publicKey", () => {
      expect(publicKeyToAddress(undefined)).to.be.null;
    });
  });

  describe("areSolanaAddressesEqual", () => {
    it("should return true for equal addresses", () => {
      expect(
        areSolanaAddressesEqual(
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn"
        )
      ).to.be.true;
    });

    it("should return false for different addresses", () => {
      expect(
        areSolanaAddressesEqual(
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
          "TokenkegQfeZyiNwAJbNbGKPFXCWuBvf9Ss623VQ5DA"
        )
      ).to.be.false;
    });

    it("should be case-sensitive (unlike Ethereum)", () => {
      expect(
        areSolanaAddressesEqual(
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
          "fdkjvwcjne6wecbgdydfpcfgs14ajnvsufwqrywln4tn"
        )
      ).to.be.false;
    });

    it("should return false for null/undefined", () => {
      expect(
        areSolanaAddressesEqual(
          null,
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn"
        )
      ).to.be.false;
      expect(
        areSolanaAddressesEqual(
          "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
          null
        )
      ).to.be.false;
      expect(areSolanaAddressesEqual(null, null)).to.be.false;
    });

    it("should handle PublicKey objects", () => {
      const mockPublicKey1: SolanaPublicKey = {
        toBase58: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toString: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toBytes: () => new Uint8Array(32),
        equals: () => false,
      };

      const mockPublicKey2: SolanaPublicKey = {
        toBase58: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toString: () => "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn",
        toBytes: () => new Uint8Array(32),
        equals: () => false,
      };

      expect(areSolanaAddressesEqual(mockPublicKey1, mockPublicKey2)).to.be.true;
    });
  });
});

import { expect } from "chai";
import { describe, it, beforeEach, afterEach } from "mocha";
import * as sinon from "sinon";
import { SolanaStoreHandler } from "../../src/solana/SolanaStoreHandler";
import { FormoAnalytics } from "../../src/FormoAnalytics";
import { SOLANA_CHAIN_IDS } from "../../src/solana/types";
import {
  SolanaClientStore,
  SolanaClientState,
  SolanaTransactionRecord,
} from "../../src/solana/storeTypes";

describe("SolanaStoreHandler", () => {
  let sandbox: sinon.SinonSandbox;
  let mockFormo: sinon.SinonStubbedInstance<FormoAnalytics>;

  const MOCK_ADDRESS = "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn";

  // -- Mock Store Helper --

  function createMockStore(
    initialState?: Partial<SolanaClientState>
  ): SolanaClientStore & {
    _setState: (partial: Partial<SolanaClientState>) => void;
    _state: SolanaClientState;
  } {
    const defaultState: SolanaClientState = {
      transactions: {},
      wallet: { status: "disconnected" },
      cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
      lastUpdatedAt: Date.now(),
      ...initialState,
    };

    let state = { ...defaultState };
    const listeners: Array<{
      selector?: (state: SolanaClientState) => unknown;
      listener: (...args: unknown[]) => void;
    }> = [];

    const store: SolanaClientStore & {
      _setState: (partial: Partial<SolanaClientState>) => void;
      _state: SolanaClientState;
    } = {
      getState: () => state,
      get _state() { return state; },

      subscribe: (
        selectorOrListener: unknown,
        listenerOrOptions?: unknown,
        _options?: unknown
      ): (() => void) => {
        if (typeof listenerOrOptions === "function") {
          // Selector-based subscription: subscribe(selector, listener, options?)
          const entry = {
            selector: selectorOrListener as (state: SolanaClientState) => unknown,
            listener: listenerOrOptions as (...args: unknown[]) => void,
          };
          listeners.push(entry);
          return () => {
            const idx = listeners.indexOf(entry);
            if (idx >= 0) listeners.splice(idx, 1);
          };
        } else {
          // Full state subscription: subscribe(listener)
          const entry = {
            listener: selectorOrListener as (...args: unknown[]) => void,
          };
          listeners.push(entry);
          return () => {
            const idx = listeners.indexOf(entry);
            if (idx >= 0) listeners.splice(idx, 1);
          };
        }
      },

      _setState(partial: Partial<SolanaClientState>) {
        const prev = { ...state };
        state = { ...state, ...partial };
        for (const entry of listeners) {
          if (entry.selector) {
            const prevSelected = entry.selector(prev);
            const selected = entry.selector(state);
            if (prevSelected !== selected) {
              entry.listener(selected, prevSelected);
            }
          } else {
            entry.listener(state, prev);
          }
        }
      },
    };

    return store;
  }

  beforeEach(() => {
    sandbox = sinon.createSandbox();
    mockFormo = {
      connect: sandbox.stub().resolves(),
      disconnect: sandbox.stub().resolves(),
      chain: sandbox.stub().resolves(),
      transaction: sandbox.stub().resolves(),
      signature: sandbox.stub().resolves(),
      isAutocaptureEnabled: sandbox.stub().returns(true),
    } as any;
  });

  afterEach(() => {
    sandbox.restore();
  });

  // -- Constructor --

  describe("Constructor", () => {
    it("should auto-detect cluster from store endpoint", () => {
      const store = createMockStore(); // default endpoint is devnet
      const handler = new SolanaStoreHandler(mockFormo as any, store);
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);
      handler.cleanup();
    });

    it("should default to mainnet-beta when endpoint is unrecognized", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://custom-rpc.example.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);
      handler.cleanup();
    });

    it("should use provided cluster", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store, { cluster: "devnet" });
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);
      handler.cleanup();
    });
  });

  // -- Wallet Connect/Disconnect --

  describe("Wallet Connection Tracking", () => {
    it("should emit connect event when wallet transitions to connected", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store, { cluster: "devnet" });

      store._setState({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });

      expect(mockFormo.connect.calledOnce).to.be.true;
      expect(mockFormo.connect.firstCall.args[0].address).to.equal(MOCK_ADDRESS);
      expect(mockFormo.connect.firstCall.args[0].chainId).to.equal(SOLANA_CHAIN_IDS["devnet"]);
      expect(mockFormo.connect.firstCall.args[1]!.providerName).to.equal("Phantom");

      handler.cleanup();
    });

    it("should emit disconnect event when wallet transitions to disconnected", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      // Initial connect event
      expect(mockFormo.connect.calledOnce).to.be.true;

      // Disconnect
      store._setState({ wallet: { status: "disconnected" } });

      expect(mockFormo.disconnect.calledOnce).to.be.true;
      expect(mockFormo.disconnect.firstCall.args[0]!.address).to.equal(MOCK_ADDRESS);

      handler.cleanup();
    });

    it("should emit disconnect event when wallet transitions from connected to error", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(mockFormo.connect.calledOnce).to.be.true;

      // Transition to error state
      store._setState({
        wallet: { status: "error", connectorId: "phantom", error: new Error("Connection lost") },
      });

      expect(mockFormo.disconnect.calledOnce).to.be.true;
      expect(mockFormo.disconnect.firstCall.args[0]!.address).to.equal(MOCK_ADDRESS);

      handler.cleanup();
    });

    it("should detect already-connected wallet on initialization", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "solflare",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "solflare", name: "Solflare" },
            disconnect: async () => {},
          },
        },
      });

      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(mockFormo.connect.calledOnce).to.be.true;
      expect(mockFormo.connect.firstCall.args[0].address).to.equal(MOCK_ADDRESS);

      handler.cleanup();
    });

    it("should not emit connect for disconnected wallet on init", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(mockFormo.connect.called).to.be.false;

      handler.cleanup();
    });

    it("should block system addresses", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      store._setState({
        wallet: {
          status: "connected",
          connectorId: "test",
          session: {
            account: { address: "11111111111111111111111111111111" },
            connector: { id: "test", name: "Test" },
            disconnect: async () => {},
          },
        },
      });

      expect(mockFormo.connect.called).to.be.false;

      handler.cleanup();
    });

    it("should handle account switch (connected → connected with different address)", () => {
      const MOCK_ADDRESS_2 = "7EcDhSYGxXyscszYEp35KHN8vvw3svAuLKTzXwCFLtV";
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      // Initial connect
      expect(mockFormo.connect.calledOnce).to.be.true;

      // Switch to different account within same wallet
      store._setState({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS_2 },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });

      // Should disconnect old address and connect new one
      expect(mockFormo.disconnect.calledOnce).to.be.true;
      expect(mockFormo.disconnect.firstCall.args[0]!.address).to.equal(MOCK_ADDRESS);
      expect(mockFormo.connect.calledTwice).to.be.true;
      expect(mockFormo.connect.secondCall.args[0].address).to.equal(MOCK_ADDRESS_2);

      handler.cleanup();
    });

    it("should handle connector change with same address", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(mockFormo.connect.calledOnce).to.be.true;
      expect(mockFormo.connect.firstCall.args[1]!.providerName).to.equal("Phantom");

      // Switch connector (same address, different wallet)
      store._setState({
        wallet: {
          status: "connected",
          connectorId: "solflare",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "solflare", name: "Solflare" },
            disconnect: async () => {},
          },
        },
      });

      // Should disconnect old and connect with new provider metadata
      expect(mockFormo.disconnect.calledOnce).to.be.true;
      expect(mockFormo.connect.calledTwice).to.be.true;
      expect(mockFormo.connect.secondCall.args[1]!.providerName).to.equal("Solflare");

      handler.cleanup();
    });
  });

  // -- Transaction Tracking --

  describe("Transaction Tracking", () => {
    let store: ReturnType<typeof createMockStore>;
    let handler: SolanaStoreHandler;

    beforeEach(() => {
      store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      handler = new SolanaStoreHandler(mockFormo as any, store);
      // Clear the connect call from init
      mockFormo.transaction.resetHistory();
    });

    afterEach(() => {
      handler.cleanup();
    });

    it("should emit STARTED when transaction enters sending state", () => {
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });

      expect(mockFormo.transaction.calledOnce).to.be.true;
      expect(mockFormo.transaction.firstCall.args[0].status).to.equal("started");
      expect(mockFormo.transaction.firstCall.args[0].address).to.equal(MOCK_ADDRESS);
    });

    it("should emit BROADCASTED when transaction enters waiting state with signature", () => {
      // First: sending
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });

      // Then: waiting (with signature)
      store._setState({
        transactions: {
          tx1: { status: "waiting", signature: "tx_sig_abc", lastUpdatedAt: Date.now() },
        },
      });

      expect(mockFormo.transaction.calledTwice).to.be.true;
      expect(mockFormo.transaction.secondCall.args[0].status).to.equal("broadcasted");
      expect(mockFormo.transaction.secondCall.args[0].transactionHash).to.equal("tx_sig_abc");
    });

    it("should emit CONFIRMED when transaction is confirmed", () => {
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "confirmed", signature: "tx_sig_123", lastUpdatedAt: Date.now() },
        },
      });

      const lastCall = mockFormo.transaction.lastCall.args[0];
      expect(lastCall.status).to.equal("confirmed");
      expect(lastCall.transactionHash).to.equal("tx_sig_123");
    });

    it("should emit REVERTED when transaction fails after being sent (waiting)", () => {
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "waiting", signature: "tx_sig", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "failed", signature: "tx_sig", error: "InstructionError", lastUpdatedAt: Date.now() },
        },
      });

      const lastCall = mockFormo.transaction.lastCall.args[0];
      expect(lastCall.status).to.equal("reverted");
    });

    it("should emit REJECTED when transaction fails during sending", () => {
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "failed", error: "User rejected", lastUpdatedAt: Date.now() },
        },
      });

      const lastCall = mockFormo.transaction.lastCall.args[0];
      expect(lastCall.status).to.equal("rejected");
    });

    it("should emit REJECTED when transaction fails before sending", () => {
      store._setState({
        transactions: {
          tx1: { status: "idle", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "failed", error: "User rejected", lastUpdatedAt: Date.now() },
        },
      });

      const lastCall = mockFormo.transaction.lastCall.args[0];
      expect(lastCall.status).to.equal("rejected");
    });

    it("should track multiple transactions independently", () => {
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });
      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
          tx2: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });

      // tx1 STARTED + tx2 STARTED
      expect(mockFormo.transaction.callCount).to.equal(2);
    });

    it("should not emit events when not connected", () => {
      // Disconnect first
      store._setState({ wallet: { status: "disconnected" } });
      mockFormo.transaction.resetHistory();

      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });

      expect(mockFormo.transaction.called).to.be.false;
    });

    it("should deduplicate same transaction status", () => {
      const tx: SolanaTransactionRecord = { status: "sending", lastUpdatedAt: Date.now() };
      store._setState({ transactions: { tx1: tx } });
      // Force re-emit by creating new object reference
      store._setState({ transactions: { tx1: { ...tx, lastUpdatedAt: Date.now() + 1 } } });

      // Should only have one STARTED (deduplicated)
      expect(mockFormo.transaction.callCount).to.equal(1);
    });
  });

  // -- Transaction survives disconnect --

  describe("Transaction events after disconnect", () => {
    it("should emit CONFIRMED even after wallet disconnects", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);
      mockFormo.transaction.resetHistory();

      // Start transaction
      store._setState({
        transactions: { tx1: { status: "sending", lastUpdatedAt: Date.now() } },
      });
      expect(mockFormo.transaction.calledOnce).to.be.true;
      expect(mockFormo.transaction.firstCall.args[0].status).to.equal("started");

      // Disconnect while tx is in-flight
      store._setState({ wallet: { status: "disconnected" } });

      // Transaction confirms after disconnect
      store._setState({
        transactions: { tx1: { status: "confirmed", signature: "sig123", lastUpdatedAt: Date.now() } },
      });

      // Should still emit CONFIRMED with the original sender address
      const confirmedCall = mockFormo.transaction.lastCall.args[0];
      expect(confirmedCall.status).to.equal("confirmed");
      expect(confirmedCall.address).to.equal(MOCK_ADDRESS);
      expect(confirmedCall.transactionHash).to.equal("sig123");

      handler.cleanup();
    });
  });

  // -- Cluster Detection --

  describe("Cluster Detection", () => {
    it("should detect devnet from store endpoint", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);

      handler.cleanup();
    });

    it("should detect testnet from store endpoint", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.testnet.solana.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["testnet"]);

      handler.cleanup();
    });

    it("should detect localnet from localhost endpoint", () => {
      const store = createMockStore({
        cluster: { endpoint: "http://localhost:8899", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["localnet"]);

      handler.cleanup();
    });

    it("should prefer explicit cluster option over auto-detection", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store, {
        cluster: "mainnet-beta",
      });

      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);

      handler.cleanup();
    });

    it("should react to cluster endpoint changes in the store", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);

      // Switch to mainnet
      store._setState({
        cluster: { endpoint: "https://api.mainnet-beta.solana.com", status: "ready" },
      });

      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);
      expect(mockFormo.chain.calledOnce).to.be.true;
      expect(mockFormo.chain.firstCall.args[0].chainId).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);
      expect(mockFormo.chain.firstCall.args[0].address).to.equal(MOCK_ADDRESS);

      handler.cleanup();
    });

    it("should not emit chain event when not connected", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      store._setState({
        cluster: { endpoint: "https://api.mainnet-beta.solana.com", status: "ready" },
      });

      // chainId should update but no event emitted
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);
      expect(mockFormo.chain.called).to.be.false;

      handler.cleanup();
    });

    it("should use correct chainId when wallet and cluster change in same update", () => {
      const store = createMockStore({
        cluster: { endpoint: "https://api.devnet.solana.com", status: "ready" },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store);
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);

      // Batch both wallet connect + cluster change in one setState
      store._setState({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
        cluster: { endpoint: "https://api.mainnet-beta.solana.com", status: "ready" },
      });

      // Connect event should use mainnet chainId, not stale devnet
      expect(mockFormo.connect.calledOnce).to.be.true;
      expect(mockFormo.connect.firstCall.args[0].chainId).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);

      handler.cleanup();
    });
  });

  // -- Autocapture Disabled --

  describe("Autocapture Disabled", () => {
    it("should not emit events when autocapture is disabled", () => {
      mockFormo.isAutocaptureEnabled.returns(false);

      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      store._setState({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });

      expect(mockFormo.connect.called).to.be.false;

      store._setState({
        transactions: {
          tx1: { status: "sending", lastUpdatedAt: Date.now() },
        },
      });

      expect(mockFormo.transaction.called).to.be.false;

      handler.cleanup();
    });
  });

  // -- setCluster --

  describe("setCluster", () => {
    it("should update chainId", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store, {
        cluster: "mainnet-beta",
      });

      handler.setCluster("devnet");
      expect(handler.getChainId()).to.equal(SOLANA_CHAIN_IDS["devnet"]);

      handler.cleanup();
    });

    it("should emit chain event when connected and cluster changes", () => {
      const store = createMockStore({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });
      const handler = new SolanaStoreHandler(mockFormo as any, store, {
        cluster: "mainnet-beta",
      });

      handler.setCluster("devnet");

      expect(mockFormo.chain.calledOnce).to.be.true;
      expect(mockFormo.chain.firstCall.args[0].chainId).to.equal(SOLANA_CHAIN_IDS["devnet"]);

      handler.cleanup();
    });
  });

  // -- Cleanup --

  describe("Cleanup", () => {
    it("should unsubscribe from store on cleanup", () => {
      const store = createMockStore();
      const handler = new SolanaStoreHandler(mockFormo as any, store);

      handler.cleanup();

      // After cleanup, state changes should not trigger events
      store._setState({
        wallet: {
          status: "connected",
          connectorId: "phantom",
          session: {
            account: { address: MOCK_ADDRESS },
            connector: { id: "phantom", name: "Phantom" },
            disconnect: async () => {},
          },
        },
      });

      expect(mockFormo.connect.called).to.be.false;
    });
  });
});

import { expect } from "chai";
import { describe, it } from "mocha";
import {
  SOLANA_CHAIN_IDS,
  SOLANA_CLUSTERS_BY_ID,
  DEFAULT_SOLANA_CHAIN_ID,
  isSolanaChainId,
} from "../../src/solana/types";

describe("Solana Types", () => {
  describe("Chain ID Constants", () => {
    it("should have correct chain ID for mainnet-beta", () => {
      expect(SOLANA_CHAIN_IDS["mainnet-beta"]).to.equal(900001);
    });

    it("should have correct chain ID for testnet", () => {
      expect(SOLANA_CHAIN_IDS["testnet"]).to.equal(900002);
    });

    it("should have correct chain ID for devnet", () => {
      expect(SOLANA_CHAIN_IDS["devnet"]).to.equal(900003);
    });

    it("should have correct chain ID for localnet", () => {
      expect(SOLANA_CHAIN_IDS["localnet"]).to.equal(900004);
    });

    it("should have reverse mapping from ID to cluster", () => {
      expect(SOLANA_CLUSTERS_BY_ID[900001]).to.equal("mainnet-beta");
      expect(SOLANA_CLUSTERS_BY_ID[900002]).to.equal("testnet");
      expect(SOLANA_CLUSTERS_BY_ID[900003]).to.equal("devnet");
      expect(SOLANA_CLUSTERS_BY_ID[900004]).to.equal("localnet");
    });

    it("should have mainnet-beta as default chain ID", () => {
      expect(DEFAULT_SOLANA_CHAIN_ID).to.equal(SOLANA_CHAIN_IDS["mainnet-beta"]);
    });

    it("should have high chain IDs to avoid collision with EVM chains", () => {
      // EVM chains typically have IDs < 100000
      Object.values(SOLANA_CHAIN_IDS).forEach((chainId) => {
        expect(chainId).to.be.greaterThan(100000);
      });
    });
  });

  describe("isSolanaChainId", () => {
    it("should return true for Solana chain IDs", () => {
      expect(isSolanaChainId(900001)).to.be.true;
      expect(isSolanaChainId(900002)).to.be.true;
      expect(isSolanaChainId(900003)).to.be.true;
      expect(isSolanaChainId(900004)).to.be.true;
    });

    it("should return false for EVM chain IDs", () => {
      expect(isSolanaChainId(1)).to.be.false;
      expect(isSolanaChainId(137)).to.be.false;
    });

    it("should return false for null/undefined", () => {
      expect(isSolanaChainId(null)).to.be.false;
      expect(isSolanaChainId(undefined)).to.be.false;
    });
  });
});

import { describe, it } from "mocha";
import { expect } from "chai";
import { JSON_PREFIX, KEY_PREFIX } from "../../src/storage/constant";

/**
 * Tests to ensure storage prefix values remain stable for backward compatibility.
 *
 * IMPORTANT: These prefixes are used when storing data in cookies/localStorage.
 * If these values change, existing users will:
 * - Lose all stored analytics data
 * - Appear as new visitors
 * - Have accumulated storage from old prefix as orphaned data
 *
 * If you need to change these values, you MUST implement a migration strategy.
 */
describe("Storage Constants - Backward Compatibility", () => {
  describe("Storage prefix values must not change", () => {
    it("JSON_PREFIX should have stable value", () => {
      expect(JSON_PREFIX).to.equal("__json=");
    });

    it("KEY_PREFIX should have stable value", () => {
      expect(KEY_PREFIX).to.equal("formo");
    });
  });
});

import { describe, it, beforeEach, afterEach } from "mocha";
import { expect } from "chai";
import * as sinon from "sinon";
import { JSDOM } from "jsdom";
import { FormoAnalytics } from "../src/FormoAnalytics";
import { initStorageManager, cookie } from "../src/storage";
import { ACTIVE_WALLET_KEY } from "../src/constants";
import type { TrackingOptions } from "../src/types";

/**
 * Timezone-based tracking opt-out.
 *
 * Verifies that `tracking.excludeTimezones` gates the single `shouldTrack()`
 * choke point that all events (page/identify/connect/track/...) flow through,
 * so visitors in an excluded timezone produce no events at all.
 */
describe("Tracking timezone exclusion", () => {
  let sandbox: sinon.SinonSandbox;
  let jsdom: JSDOM;
  const originalIntl = global.Intl;

  function stubTimezone(timeZone: string) {
    Object.defineProperty(global, "Intl", {
      value: {
        DateTimeFormat: () => ({
          resolvedOptions: () => ({ timeZone }),
        }),
      },
      writable: true,
      configurable: true,
    });
  }

  async function makeAnalytics(
    tracking?: boolean | TrackingOptions
  ): Promise<FormoAnalytics> {
    // Use wagmi mode to skip browser-dependent provider detection.
    const mockWagmiConfig = {
      subscribe: sandbox.stub().returns(() => {}),
      state: {
        status: "disconnected",
        connections: new Map(),
        current: undefined,
        chainId: undefined,
      },
      _internal: { store: { subscribe: sandbox.stub().returns(() => {}) } },
    };
    return FormoAnalytics.init("test-write-key", {
      tracking,
      wagmi: { config: mockWagmiConfig as any },
    });
  }

  beforeEach(() => {
    sandbox = sinon.createSandbox();
    jsdom = new JSDOM("<!DOCTYPE html><html><head></head><body></body></html>", {
      url: "https://example.com",
    });
    Object.defineProperty(global, "window", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "document", {
      value: jsdom.window.document, writable: true, configurable: true,
    });
    Object.defineProperty(global, "location", {
      value: jsdom.window.location, writable: true, configurable: true,
    });
    Object.defineProperty(global, "globalThis", {
      value: jsdom.window, writable: true, configurable: true,
    });
    Object.defineProperty(global, "navigator", {
      value: jsdom.window.navigator, writable: true, configurable: true,
    });
    Object.defineProperty(global, "localStorage", {
      value: jsdom.window.localStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "sessionStorage", {
      value: jsdom.window.sessionStorage, writable: true, configurable: true,
    });
    Object.defineProperty(global, "crypto", {
      value: { randomUUID: () => "mock-uuid-1234" },
      writable: true, configurable: true,
    });

    initStorageManager("test-write-key");
  });

  afterEach(() => {
    sandbox.restore();
    delete (global as any).window;
    delete (global as any).document;
    delete (global as any).location;
    delete (global as any).globalThis;
    delete (global as any).navigator;
    delete (global as any).localStorage;
    delete (global as any).sessionStorage;
    delete (global as any).crypto;
    global.Intl = originalIntl;
    if (jsdom) jsdom.window.close();
  });

  it("blocks tracking when the visitor timezone is excluded", async () => {
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });
    expect((formo as any).shouldTrack()).to.equal(false);
  });

  it("allows tracking when the visitor timezone is not excluded", async () => {
    stubTimezone("America/New_York");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });
    expect((formo as any).shouldTrack()).to.equal(true);
  });

  it("matches the timezone case-insensitively", async () => {
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({ excludeTimezones: ["europe/london"] });
    expect((formo as any).shouldTrack()).to.equal(false);
  });

  it("allows tracking when no excludeTimezones are configured", async () => {
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({});
    expect((formo as any).shouldTrack()).to.equal(true);
  });

  it("does not block when the timezone cannot be resolved", async () => {
    stubTimezone("");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });
    expect((formo as any).shouldTrack()).to.equal(true);
  });

  it("prevents identify and connect events from being enqueued", async () => {
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });
    const addEvent = sandbox.stub(
      (formo as any).eventManager,
      "addEvent"
    ).resolves();

    await formo.identify({
      address: "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e",
      userId: "user-1",
    });
    await formo.connect({
      chainId: 1,
      address: "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e",
    });

    expect(addEvent.called).to.equal(false);
  });

  it("does not persist wallet/identity state for an excluded visitor", async () => {
    const ADDRESS = "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e";
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });

    await formo.identify({ address: ADDRESS, rdns: "io.metamask" });
    await formo.connect({ chainId: 1, address: ADDRESS });
    await formo.detect({ providerName: "MetaMask", rdns: "io.metamask" });

    // connect() must not have run setChainState()
    expect(formo.currentAddress).to.not.equal(ADDRESS);
    expect(formo.currentChainId).to.be.oneOf([undefined, null]);
    // identify()/detect() must not have written session markers
    const session = (formo as any).session;
    expect(session.isWalletIdentified(ADDRESS, "io.metamask")).to.equal(false);
    expect(session.isWalletDetected("io.metamask")).to.equal(false);
  });

  it("does not persist an active-wallet cookie via the autocapture/sync path", async () => {
    const ADDRESS = "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e";
    stubTimezone("Europe/London");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });

    // syncWalletState() is the entry point used by the EIP-1193 and Wagmi
    // autocapture handlers; it updates chain state directly, bypassing the
    // gated public connect(). The persistence guard must still suppress the
    // active-wallet cookie for a suppressed visitor.
    formo.syncWalletState({ chainId: 1, address: ADDRESS });

    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("persists an active-wallet cookie for a non-excluded visitor (control)", async () => {
    const ADDRESS = "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e";
    stubTimezone("America/New_York");
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });

    formo.syncWalletState({ chainId: 1, address: ADDRESS });

    expect(cookie().get(ACTIVE_WALLET_KEY)).to.be.ok;
  });

  // --- Host / path (current-page) suppression ---------------------------------

  const ADDRESS = "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e";

  function navigateTo(url: string) {
    jsdom.reconfigure({ url });
  }

  it("does not track or persist while on an excluded host", async () => {
    navigateTo("https://staging.example.com/");
    const formo = await makeAnalytics({ excludeHosts: ["staging.example.com"] });

    expect((formo as any).shouldTrack()).to.equal(false);
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("does not track or persist while on an excluded path", async () => {
    navigateTo("https://example.com/admin");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });

    expect((formo as any).shouldTrack()).to.equal(false);
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("does not delete an existing cookie when navigating onto an excluded path", async () => {
    // Connect on an allowed path → cookie written.
    navigateTo("https://example.com/");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.be.ok;

    // Navigate onto the excluded path → cookie must survive (no new write,
    // but no destructive delete either).
    navigateTo("https://example.com/admin");
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.be.ok;
  });

  it("resumes tracking after navigating from an excluded path to an allowed one", async () => {
    navigateTo("https://example.com/admin");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });
    expect((formo as any).shouldTrack()).to.equal(false);

    navigateTo("https://example.com/dashboard");
    expect((formo as any).shouldTrack()).to.equal(true);
  });

  it("clears stale identity when a disconnect is observed on an excluded path", async () => {
    // Learn wallet A on an allowed path.
    navigateTo("https://example.com/");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(formo.currentAddress).to.equal(ADDRESS);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.be.ok;

    // Disconnect observed while on the excluded path must clear the stale
    // wallet (memory + cookie), not leave it for later allowed events.
    navigateTo("https://example.com/admin");
    formo.syncWalletState({ chainId: 1 });
    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;

    // Back on an allowed path the stale address must not reappear.
    navigateTo("https://example.com/dashboard");
    expect((formo as any).shouldTrack()).to.equal(true);
    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
  });

  it("clears stale identity when a wallet switch is observed on an excluded path", async () => {
    const ADDRESS_B = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";
    navigateTo("https://example.com/");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(formo.currentAddress).to.equal(ADDRESS);

    // A switch to a different wallet on the excluded path must drop the stale
    // wallet without learning the new one.
    navigateTo("https://example.com/admin");
    formo.syncWalletState({ chainId: 1, address: ADDRESS_B });
    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("does not write session markers via identify/detect on an excluded path", async () => {
    navigateTo("https://example.com/admin");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });

    await formo.identify({ address: ADDRESS, rdns: "io.metamask" });
    await formo.detect({ providerName: "MetaMask", rdns: "io.metamask" });

    const session = (formo as any).session;
    expect(session.isWalletIdentified(ADDRESS, "io.metamask")).to.equal(false);
    expect(session.isWalletDetected("io.metamask")).to.equal(false);
  });

  it("does not restore the active-wallet snapshot at init on an excluded path, but keeps the cookie", async () => {
    // Seed a snapshot as if written on a previous allowed-page visit.
    cookie().set(ACTIVE_WALLET_KEY, JSON.stringify({ address: ADDRESS, chainId: 1 }), {
      path: "/",
    });
    navigateTo("https://example.com/admin");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });

    // Not restored into memory while on the excluded route...
    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    // ...but the cookie is preserved for a later allowed-page load.
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.be.ok;
  });

  it("purges the active-wallet snapshot at init for an excluded-timezone visitor", async () => {
    stubTimezone("Europe/London");
    cookie().set(ACTIVE_WALLET_KEY, JSON.stringify({ address: ADDRESS, chainId: 1 }), {
      path: "/",
    });
    const formo = await makeAnalytics({ excludeTimezones: ["Europe/London"] });

    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("does not learn identity via backfillActiveWallet while on an excluded path", async () => {
    // backfillActiveWallet() is the shared sink for the autocapture
    // signature/transaction paths; a signature/transaction observed on an
    // excluded route must not populate currentAddress.
    navigateTo("https://example.com/admin");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });

    (formo as any).backfillActiveWallet(ADDRESS, 1);

    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });

  it("backfills identity via backfillActiveWallet on an allowed path (control)", async () => {
    navigateTo("https://example.com/");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });

    (formo as any).backfillActiveWallet(ADDRESS, 1);

    expect(formo.currentAddress).to.equal(ADDRESS);
  });

  it("drops a stale EVM wallet on switch via the suppressed autocapture helper", async () => {
    // Helper shared by the EIP-1193 onAccountsChanged / onConnected listeners.
    const ADDRESS_B = "0x1095bBe769fDab716A823d0f7149CAD713d20A13";
    navigateTo("https://example.com/");
    const formo = await makeAnalytics({ excludePaths: ["/admin"] });
    formo.syncWalletState({ chainId: 1, address: ADDRESS });
    expect(formo.currentAddress).to.equal(ADDRESS);

    navigateTo("https://example.com/admin");
    (formo as any).clearStaleEvmWalletOnSwitchWhileSuppressed(ADDRESS_B);

    expect(formo.currentAddress).to.be.oneOf([undefined, null]);
    expect(cookie().get(ACTIVE_WALLET_KEY)).to.not.be.ok;
  });
});

import { describe, it } from "mocha";
import { expect } from "chai";
import { toChecksumAddress, isBlockedAddress } from "../../src/utils";
import { validateAddress } from "../../src/utils/address";
import { ZERO_ADDRESS, DEAD_ADDRESS } from "../../src/constants";
import { SOLANA_CHAIN_IDS } from "../../src/solana/types";

describe("toChecksumAddress", () => {
  it("should return the checksum of the address", () => {
    expect(
      toChecksumAddress("0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e")
    ).to.equal("0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e");
    expect(
      toChecksumAddress("0x82827bc8342a16b681afba6b979e3d1ae5f28a0e")
    ).to.equal("0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e");
  });

  it("should properly checksum the specific address from the issue", () => {
    const nonChecksummedAddress = "0x7e6ca77a7e044ba836a97beb796c124ca3a6a255";
    const expectedChecksummedAddress = "0x7E6CA77a7E044BA836a97beB796c124Ca3a6A255";

    const result = toChecksumAddress(nonChecksummedAddress);
    expect(result).to.equal(expectedChecksummedAddress);
  });

  it("should handle various address formats", () => {
    const testCases = [
      {
        input: "0x7e6ca77a7e044ba836a97beb796c124ca3a6a255",
        expected: "0x7E6CA77a7E044BA836a97beB796c124Ca3a6A255"
      },
      {
        input: "0x82827bc8342a16b681afba6b979e3d1ae5f28a0e",
        expected: "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e"
      }
    ];

    testCases.forEach(({ input, expected }) => {
      const result = toChecksumAddress(input);
      expect(result).to.equal(expected);
    });
  });

  it("should handle already checksummed addresses", () => {
    const checksummedAddress = "0x7E6CA77a7E044BA836a97beB796c124Ca3a6A255";
    const result = toChecksumAddress(checksummedAddress);
    expect(result).to.equal(checksummedAddress);
  });
});

describe("isBlockedAddress", () => {
  it("should return true for zero address", () => {
    expect(isBlockedAddress(ZERO_ADDRESS)).to.be.true;
    expect(isBlockedAddress("0x0000000000000000000000000000000000000000")).to.be.true;
    expect(isBlockedAddress("0x0000000000000000000000000000000000000000".toLowerCase())).to.be.true;
  });

  it("should return true for dead address", () => {
    expect(isBlockedAddress(DEAD_ADDRESS)).to.be.true;
    expect(isBlockedAddress("0x000000000000000000000000000000000000dEaD")).to.be.true;
    expect(isBlockedAddress("0x000000000000000000000000000000000000dead")).to.be.true;
    expect(isBlockedAddress("0x000000000000000000000000000000000000DEAD")).to.be.true;
  });

  it("should return false for normal addresses", () => {
    expect(isBlockedAddress("0x7E6CA77a7E044BA836a97beB796c124Ca3a6A255")).to.be.false;
    expect(isBlockedAddress("0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e")).to.be.false;
  });

  it("should return false for null, undefined, or empty addresses", () => {
    expect(isBlockedAddress(null)).to.be.false;
    expect(isBlockedAddress(undefined)).to.be.false;
    expect(isBlockedAddress("")).to.be.false;
    expect(isBlockedAddress("   ")).to.be.false;
  });

  it("should return false for invalid addresses", () => {
    expect(isBlockedAddress("not-an-address")).to.be.false;
    expect(isBlockedAddress("0x123")).to.be.false;
    expect(isBlockedAddress("0x1234567890123456789012345678901234567890123456789012345678901234567890")).to.be.false;
  });

  it("should handle addresses with different casing", () => {
    // Test that the function correctly handles different case versions of the same blocked address
    const zeroAddressVariants = [
      "0x0000000000000000000000000000000000000000",
      "0X0000000000000000000000000000000000000000",
      "0x0000000000000000000000000000000000000000".toLowerCase(),
      "0x0000000000000000000000000000000000000000".toUpperCase(),
    ];

    zeroAddressVariants.forEach(variant => {
      expect(isBlockedAddress(variant)).to.be.true;
    });

    const deadAddressVariants = [
      "0x000000000000000000000000000000000000dEaD",
      "0x000000000000000000000000000000000000dead",
      "0x000000000000000000000000000000000000DEAD",
      "0X000000000000000000000000000000000000DEAD",
    ];

    deadAddressVariants.forEach(variant => {
      expect(isBlockedAddress(variant)).to.be.true;
    });
  });

  it("should block addresses with invalid mixed-case checksums", () => {
    // These have deliberately wrong checksums but should still be blocked
    expect(isBlockedAddress("0x000000000000000000000000000000000000dEAD")).to.be.true;
    expect(isBlockedAddress("0x000000000000000000000000000000000000DeAd")).to.be.true;
  });
});

describe("validateAddress", () => {
  const VALID_EVM = "0x82827Bc8342a16b681AfbA6B979E3D1aE5F28a0e";
  const VALID_SOLANA = "FDKJvWcJNe6wecbgDYDFPCfgs14aJnVsUfWQRYWLn4Tn";

  it("should validate EVM address when explicit EVM chainId is provided", () => {
    expect(validateAddress(VALID_EVM, 1)).to.equal(VALID_EVM);
  });

  it("should reject Solana address when explicit EVM chainId is provided", () => {
    expect(validateAddress(VALID_SOLANA, 1)).to.be.undefined;
    expect(validateAddress(VALID_SOLANA, 137)).to.be.undefined;
  });

  it("should validate Solana address when explicit Solana chainId is provided", () => {
    expect(validateAddress(VALID_SOLANA, SOLANA_CHAIN_IDS["mainnet-beta"])).to.equal(VALID_SOLANA);
    expect(validateAddress(VALID_SOLANA, SOLANA_CHAIN_IDS["devnet"])).to.equal(VALID_SOLANA);
  });

  it("should reject EVM address when explicit Solana chainId is provided", () => {
    expect(validateAddress(VALID_EVM, SOLANA_CHAIN_IDS["mainnet-beta"])).to.be.undefined;
  });

  it("should try EVM first then Solana fallback when no chainId", () => {
    expect(validateAddress(VALID_EVM)).to.equal(VALID_EVM);
    expect(validateAddress(VALID_SOLANA)).to.equal(VALID_SOLANA);
  });

  it("should return undefined for invalid addresses", () => {
    expect(validateAddress("not-an-address")).to.be.undefined;
    expect(validateAddress("not-an-address", 1)).to.be.undefined;
    expect(validateAddress("not-an-address", SOLANA_CHAIN_IDS["mainnet-beta"])).to.be.undefined;
  });
});

