  isString,
  isNull,
  isUndefined,
  isNullOrUndefined,
  isBigInt,
  isDefined,
  isDefinedAndNotNull,
  isDefinedNotNullAndNotEmptyString,
  isTypeOfError,
  isArray,
  isBoolean,
  isNumber,
