  objectToString,
} from "../../src/validators/checks";

describe("Type Check Validators", () => {
  describe("isFunction", () => {
    it("should return true for functions", () => {
      expect(isFunction(() => {})).to.be.true;
      expect(isFunction(function () {})).to.be.true;
      expect(isFunction(async () => {})).to.be.true;
      expect(isFunction(class {})).to.be.true;
    });

    it("should return false for non-functions", () => {
      expect(isFunction("string")).to.be.false;
      expect(isFunction(123)).to.be.false;
      expect(isFunction({})).to.be.false;
      expect(isFunction([])).to.be.false;
      expect(isFunction(null)).to.be.false;
      expect(isFunction(undefined)).to.be.false;
    });
  });

  describe("isString", () => {
    it("should return true for strings", () => {
      expect(isString("")).to.be.true;
      expect(isString("hello")).to.be.true;
      expect(isString(`template`)).to.be.true;
    });

    it("should return false for non-strings", () => {
      expect(isString(123)).to.be.false;
      expect(isString({})).to.be.false;
      expect(isString(null)).to.be.false;
      expect(isString(undefined)).to.be.false;
      expect(isString([])).to.be.false;
    });
  });

  describe("isNull", () => {
    it("should return true for null", () => {
      expect(isNull(null)).to.be.true;
    });

    it("should return false for non-null values", () => {
      expect(isNull(undefined)).to.be.false;
      expect(isNull("")).to.be.false;
      expect(isNull(0)).to.be.false;
      expect(isNull(false)).to.be.false;
      expect(isNull({})).to.be.false;
    });
  });

  describe("isUndefined", () => {
    it("should return true for undefined", () => {
      expect(isUndefined(undefined)).to.be.true;
      let x;
      expect(isUndefined(x)).to.be.true;
    });

    it("should return false for defined values", () => {
      expect(isUndefined(null)).to.be.false;
      expect(isUndefined("")).to.be.false;
      expect(isUndefined(0)).to.be.false;
      expect(isUndefined(false)).to.be.false;
    });
  });

  describe("isNullOrUndefined", () => {
    it("should return true for null or undefined", () => {
      expect(isNullOrUndefined(null)).to.be.true;
      expect(isNullOrUndefined(undefined)).to.be.true;
    });

    it("should return false for other values", () => {
      expect(isNullOrUndefined("")).to.be.false;
      expect(isNullOrUndefined(0)).to.be.false;
      expect(isNullOrUndefined(false)).to.be.false;
      expect(isNullOrUndefined({})).to.be.false;
    });
  });

  describe("isBigInt", () => {
    it("should return true for BigInt values", () => {
      expect(isBigInt(BigInt(123))).to.be.true;
      expect(isBigInt(BigInt("999999999999999999999999"))).to.be.true;
      expect(isBigInt(BigInt(0))).to.be.true;
    });

    it("should return false for non-BigInt values", () => {
      expect(isBigInt(123)).to.be.false;
      expect(isBigInt("123")).to.be.false;
      expect(isBigInt(null)).to.be.false;
    });
  });

  describe("isDefined", () => {
    it("should return true for defined values", () => {
      expect(isDefined(null)).to.be.true;
      expect(isDefined("")).to.be.true;
      expect(isDefined(0)).to.be.true;
      expect(isDefined(false)).to.be.true;
      expect(isDefined({})).to.be.true;
    });

    it("should return false for undefined", () => {
      expect(isDefined(undefined)).to.be.false;
    });
  });

  describe("isDefinedAndNotNull", () => {
    it("should return true for defined, non-null values", () => {
      expect(isDefinedAndNotNull("")).to.be.true;
      expect(isDefinedAndNotNull(0)).to.be.true;
      expect(isDefinedAndNotNull(false)).to.be.true;
      expect(isDefinedAndNotNull({})).to.be.true;
    });

    it("should return false for null or undefined", () => {
      expect(isDefinedAndNotNull(null)).to.be.false;
      expect(isDefinedAndNotNull(undefined)).to.be.false;
    });
  });

  describe("isDefinedNotNullAndNotEmptyString", () => {
    it("should return true for non-empty defined values", () => {
      expect(isDefinedNotNullAndNotEmptyString("hello")).to.be.true;
      expect(isDefinedNotNullAndNotEmptyString(0)).to.be.true;
      expect(isDefinedNotNullAndNotEmptyString(false)).to.be.true;
      expect(isDefinedNotNullAndNotEmptyString({})).to.be.true;
    });

    it("should return false for null, undefined, or empty string", () => {
      expect(isDefinedNotNullAndNotEmptyString(null)).to.be.false;
      expect(isDefinedNotNullAndNotEmptyString(undefined)).to.be.false;
      expect(isDefinedNotNullAndNotEmptyString("")).to.be.false;
    });
  });

  describe("isTypeOfError", () => {
    it("should return true for Error instances", () => {
      expect(isTypeOfError(new Error("test"))).to.be.true;
      expect(isTypeOfError(new TypeError("test"))).to.be.true;
      expect(isTypeOfError(new RangeError("test"))).to.be.true;
    });

    it("should return false for non-Error values", () => {
      expect(isTypeOfError("error")).to.be.false;
      expect(isTypeOfError({ message: "error" })).to.be.false;
      expect(isTypeOfError(null)).to.be.false;
    });
  });

  describe("isArray", () => {
    it("should return true for arrays", () => {
      expect(isArray([])).to.be.true;
      expect(isArray([1, 2, 3])).to.be.true;
      expect(isArray(new Array())).to.be.true;
    });

    it("should return false for non-arrays", () => {
      expect(isArray({})).to.be.false;
      expect(isArray("array")).to.be.false;
      expect(isArray(null)).to.be.false;
      expect(isArray({ length: 0 })).to.be.false; // Array-like object
    });
  });

  describe("isBoolean", () => {
    it("should return true for booleans", () => {
      expect(isBoolean(true)).to.be.true;
      expect(isBoolean(false)).to.be.true;
    });

    it("should return false for non-booleans", () => {
      expect(isBoolean(0)).to.be.false;
      expect(isBoolean(1)).to.be.false;
      expect(isBoolean("true")).to.be.false;
      expect(isBoolean(null)).to.be.false;
    });
  });

  describe("isNumber", () => {
    it("should return true for numbers", () => {
      expect(isNumber(0)).to.be.true;
      expect(isNumber(123)).to.be.true;
      expect(isNumber(-456)).to.be.true;
      expect(isNumber(3.14)).to.be.true;
      expect(isNumber(NaN)).to.be.true; // NaN is typeof number
      expect(isNumber(Infinity)).to.be.true;
    });

    it("should return false for non-numbers", () => {
      expect(isNumber("123")).to.be.false;
      expect(isNumber(null)).to.be.false;
      expect(isNumber(undefined)).to.be.false;
      expect(isNumber(BigInt(123))).to.be.false;
    });
  });

  describe("isObject", () => {
    it("should return true for objects", () => {
      expect(isObject({})).to.be.true;
      expect(isObject({ key: "value" })).to.be.true;
      expect(isObject([])).to.be.true; // Arrays are objects
      expect(isObject(null)).to.be.true; // null is typeof object
      expect(isObject(new Date())).to.be.true;
    });

    it("should return false for non-objects", () => {
      expect(isObject("string")).to.be.false;
      expect(isObject(123)).to.be.false;
      expect(isObject(undefined)).to.be.false;
      expect(isObject(() => {})).to.be.false;
    });
  });

  describe("isObjectAndNotNull", () => {
    it("should return true for non-null, non-array objects", () => {
      expect(isObjectAndNotNull({})).to.be.true;
      expect(isObjectAndNotNull({ key: "value" })).to.be.true;
      expect(isObjectAndNotNull(new Date())).to.be.true;
    });

    it("should return false for null, arrays, and primitives", () => {
      expect(isObjectAndNotNull(null)).to.be.false;
      expect(isObjectAndNotNull([])).to.be.false;
      expect(isObjectAndNotNull("string")).to.be.false;
      expect(isObjectAndNotNull(123)).to.be.false;
    });
  });

  describe("isRegExp", () => {
    it("should return true for RegExp", () => {
      expect(isRegExp(/test/)).to.be.true;
      expect(isRegExp(new RegExp("test"))).to.be.true;
      expect(isRegExp(/test/gi)).to.be.true;
    });

    it("should return false for non-RegExp", () => {
      expect(isRegExp("/test/")).to.be.false;
      expect(isRegExp({})).to.be.false;
      expect(isRegExp(null)).to.be.false;
    });
  });

  describe("isDate", () => {
    it("should return true for Date objects", () => {
      expect(isDate(new Date())).to.be.true;
      expect(isDate(new Date("2024-01-01"))).to.be.true;
    });

    it("should return false for non-Date values", () => {
      expect(isDate("2024-01-01")).to.be.false;
      expect(isDate(Date.now())).to.be.false;
      expect(isDate({})).to.be.false;
      expect(isDate(null)).to.be.false;
    });
  });

  describe("isError", () => {
    it("should return true for Error instances", () => {
      expect(isError(new Error())).to.be.true;
      expect(isError(new TypeError())).to.be.true;
      expect(isError(new SyntaxError())).to.be.true;
    });

    it("should return false for non-Error values", () => {
      expect(isError({ message: "error" })).to.be.false;
      expect(isError("error")).to.be.false;
      expect(isError(null)).to.be.false;
    });
  });

  describe("isPrimitive", () => {
    it("should return true for primitives", () => {
      expect(isPrimitive(null)).to.be.true;
      expect(isPrimitive(undefined)).to.be.true;
      expect(isPrimitive(true)).to.be.true;
      expect(isPrimitive(false)).to.be.true;
      expect(isPrimitive(123)).to.be.true;
      expect(isPrimitive("string")).to.be.true;
      expect(isPrimitive(Symbol("sym"))).to.be.true;
    });

    it("should return false for non-primitives", () => {
      expect(isPrimitive({})).to.be.false;
      expect(isPrimitive([])).to.be.false;
      expect(isPrimitive(() => {})).to.be.false;
      expect(isPrimitive(new Date())).to.be.false;
    });
  });

  describe("objectToString", () => {
    it("should return correct string representation", () => {
      expect(objectToString({})).to.equal("[object Object]");
      expect(objectToString([])).to.equal("[object Array]");
      expect(objectToString(new Date())).to.equal("[object Date]");
      expect(objectToString(/test/)).to.equal("[object RegExp]");
      expect(objectToString(null)).to.equal("[object Null]");
      expect(objectToString(undefined)).to.equal("[object Undefined]");
      expect(objectToString("string")).to.equal("[object String]");
      expect(objectToString(123)).to.equal("[object Number]");
    });
  });
});

import { describe, it } from "mocha";
import { expect } from "chai";
import { isNetworkError } from "../../src/validators/network";

describe("isNetworkError", () => {
  describe("valid network errors", () => {
    it("should return true for Chrome network error", () => {
      const error = new TypeError("network error");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Chrome fetch failed", () => {
      const error = new TypeError("Failed to fetch");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Firefox network error", () => {
      const error = new TypeError(
        "NetworkError when attempting to fetch resource."
      );
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Safari 16 offline error", () => {
      const error = new TypeError(
        "The Internet connection appears to be offline."
      );
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Safari 17+ load failed (without stack)", () => {
      const error = new TypeError("Load failed");
      // Safari 17+ network errors have no stack
      Object.defineProperty(error, "stack", { value: undefined });
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for cross-fetch network error", () => {
      const error = new TypeError("Network request failed");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Undici fetch failed", () => {
      const error = new TypeError("fetch failed");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for Undici terminated", () => {
      const error = new TypeError("terminated");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for DOMException TimeoutError", () => {
      const error = new DOMException("The operation was aborted due to timeout", "TimeoutError");
      expect(isNetworkError(error)).to.be.true;
    });

    it("should return true for DOMException NetworkError", () => {
      const error = new DOMException("Failed to fetch", "NetworkError");
      expect(isNetworkError(error)).to.be.true;
    });
  });

  describe("non-network errors", () => {
    it("should return false for Safari 17+ load failed (with stack)", () => {
      const error = new TypeError("Load failed");
      // Regular errors have a stack trace
      expect(error.stack).to.not.be.undefined;
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for non-TypeError", () => {
      const error = new Error("network error");
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for TypeError with different message", () => {
      const error = new TypeError("Cannot read property 'x' of undefined");
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for null", () => {
      expect(isNetworkError(null)).to.be.false;
    });

    it("should return false for undefined", () => {
      expect(isNetworkError(undefined)).to.be.false;
    });

    it("should return false for string", () => {
      expect(isNetworkError("network error")).to.be.false;
    });

    it("should return false for plain object", () => {
      expect(isNetworkError({ message: "network error", name: "TypeError" })).to
        .be.false;
    });

    it("should return false for non-string message", () => {
      const error = new TypeError();
      (error as any).message = 123;
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for random TypeError messages", () => {
      const messages = [
        "null is not an object",
        "undefined is not a function",
        "Cannot convert undefined or null to object",
        "Assignment to constant variable",
      ];

      messages.forEach((message) => {
        const error = new TypeError(message);
        expect(isNetworkError(error)).to.be.false;
      });
    });
  });

  describe("edge cases", () => {
    it("should return false for empty TypeError", () => {
      const error = new TypeError("");
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for TypeError with partial match", () => {
      const error = new TypeError("network");
      expect(isNetworkError(error)).to.be.false;
    });

    it("should be case-sensitive for error messages", () => {
      const error = new TypeError("Network Error"); // Different case
      expect(isNetworkError(error)).to.be.false;
    });

    it("should return false for error without response property", () => {
      const error = { name: "TypeError", message: "custom error" };
      expect(isNetworkError(error)).to.be.false;
    });
  });
});

import { describe, it } from "mocha";
import { expect } from "chai";
import {
  extractFunctionArgs,
  flattenObject,
  buildSafeFunctionArgs,
  concatCalldataWithSuffix,
  AbiItem,
} from "../../src/wagmi/utils";

describe("wagmi/utils", () => {
  describe("concatCalldataWithSuffix", () => {
    const base = "0xa9059cbb00000000000000000000000000000000";

    it("concatenates calldata and suffix when dataSuffix is present", () => {
      const suffix = "0x74657374070080218021802180218021802180218021";
      const result = concatCalldataWithSuffix(base, suffix);
      expect(result).to.equal(base + suffix.slice(2));
    });

    it("returns encodedData unchanged when dataSuffix is undefined", () => {
      expect(concatCalldataWithSuffix(base, undefined)).to.equal(base);
    });

    it("returns encodedData unchanged when dataSuffix is empty string", () => {
      expect(concatCalldataWithSuffix(base, "")).to.equal(base);
    });

    it("returns encodedData unchanged when dataSuffix is '0x'", () => {
      expect(concatCalldataWithSuffix(base, "0x")).to.equal(base);
    });

    it("concatenates valid short suffix (e.g. 1-byte hex 'ab')", () => {
      expect(concatCalldataWithSuffix(base, "ab")).to.equal(base + "ab");
      expect(concatCalldataWithSuffix(base, "0xab")).to.equal(base + "ab");
    });

    it("strips 0x from suffix in fallback path (suffix without prefix)", () => {
      const suffixNoPrefix = "74657374070080218021802180218021802180218021";
      const result = concatCalldataWithSuffix(base, "0x" + suffixNoPrefix);
      expect(result).to.equal(base + suffixNoPrefix);
    });
  });

  describe("flattenObject", () => {
    it("should return flat object unchanged", () => {
      const result = flattenObject({
        x: "100",
        y: "200",
      });

      expect(result).to.deep.equal({
        x: "100",
        y: "200",
      });
    });

    it("should flatten nested object with underscore separator", () => {
      const result = flattenObject({
        o: {
          x: "100",
          y: "200",
        },
      });

      expect(result).to.deep.equal({
        o_x: "100",
        o_y: "200",
      });
    });

    it("should flatten deeply nested objects", () => {
      const result = flattenObject({
        o: {
          x: "100",
          inner: {
            a: "42",
            b: "0xRecipient",
          },
        },
      });

      expect(result).to.deep.equal({
        o_x: "100",
        o_inner_a: "42",
        o_inner_b: "0xRecipient",
      });
    });

    it("should handle arrays as leaf values (not flatten them)", () => {
      const result = flattenObject({
        amounts: ["100", "200", "300"],
        nested: {
          values: [1, 2, 3],
        },
      });

      expect(result).to.deep.equal({
        amounts: ["100", "200", "300"],
        nested_values: [1, 2, 3],
      });
    });

    it("should handle null values as leaf values", () => {
      const result = flattenObject({
        a: null,
        b: {
          c: null,
        },
      });

      expect(result).to.deep.equal({
        a: null,
        b_c: null,
      });
    });

    it("should handle mixed primitive types", () => {
      const result = flattenObject({
        str: "hello",
        num: 42,
        bool: true,
        nested: {
          str: "world",
          num: 100,
        },
      });

      expect(result).to.deep.equal({
        str: "hello",
        num: 42,
        bool: true,
        nested_str: "world",
        nested_num: 100,
      });
    });

    it("should handle empty objects", () => {
      const result = flattenObject({});
      expect(result).to.deep.equal({});
    });

    it("should handle nested empty objects", () => {
      const result = flattenObject({
        a: {},
        b: {
          c: {},
        },
      });

      expect(result).to.deep.equal({});
    });

    it("should handle triple nesting", () => {
      const result = flattenObject({
        level1: {
          level2: {
            level3: {
              value: "deep",
            },
          },
        },
      });

      expect(result).to.deep.equal({
        level1_level2_level3_value: "deep",
      });
    });

    it("should respect provided prefix", () => {
      const result = flattenObject(
        {
          x: "100",
          inner: {
            a: "42",
          },
        },
        "order"
      );

      expect(result).to.deep.equal({
        order_x: "100",
        order_inner_a: "42",
      });
    });

    it("should handle Solidity struct-like data", () => {
      // Matches the Lambda example from the request
      const result = flattenObject({
        o: {
          x: "100",
          inner: {
            a: "42",
            b: "0xRecipient0000000000000000000000000000000",
          },
        },
      });

      expect(result).to.deep.equal({
        o_x: "100",
        o_inner_a: "42",
        o_inner_b: "0xRecipient0000000000000000000000000000000",
      });
    });
  });

  describe("extractFunctionArgs", () => {
    it("should extract function args from ABI and args array", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "transfer",
          inputs: [
            { name: "to", type: "address" },
            { name: "amount", type: "uint256" },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "transfer", [
        "0x1234567890123456789012345678901234567890",
        BigInt("1000000000000000000"),
      ]);

      expect(result).to.deep.equal({
        to: "0x1234567890123456789012345678901234567890",
        amount: "1000000000000000000",
      });
    });

    it("should convert BigInt values to strings", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "repayBorrow",
          inputs: [{ name: "repayAmount", type: "uint256" }],
        },
      ];

      const result = extractFunctionArgs(abi, "repayBorrow", [BigInt(3300000)]);

      expect(result).to.deep.equal({
        repayAmount: "3300000",
      });
    });

    it("should handle arrays containing BigInt values", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "batchTransfer",
          inputs: [
            { name: "recipients", type: "address[]" },
            { name: "amounts", type: "uint256[]" },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "batchTransfer", [
        ["0xaddr1", "0xaddr2"],
        [BigInt(100), BigInt(200)],
      ]);

      expect(result).to.deep.equal({
        recipients: ["0xaddr1", "0xaddr2"],
        amounts: ["100", "200"],
      });
    });

    it("should use indexed names for unnamed inputs", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "anonymous",
          inputs: [
            { name: "", type: "address" },
            { name: "", type: "uint256" },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "anonymous", [
        "0xaddr",
        BigInt(100),
      ]);

      expect(result).to.deep.equal({
        arg0: "0xaddr",
        arg1: "100",
      });
    });

    it("should return undefined if ABI is missing", () => {
      const result = extractFunctionArgs(
        undefined as any,
        "transfer",
        ["0xaddr"]
      );
      expect(result).to.be.undefined;
    });

    it("should return undefined if functionName is missing", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "transfer",
          inputs: [{ name: "to", type: "address" }],
        },
      ];

      const result = extractFunctionArgs(abi, "", ["0xaddr"]);
      expect(result).to.be.undefined;
    });

    it("should return undefined if args is not an array", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "transfer",
          inputs: [{ name: "to", type: "address" }],
        },
      ];

      const result = extractFunctionArgs(abi, "transfer", "0xaddr" as any);
      expect(result).to.be.undefined;
    });

    it("should return undefined if function is not found in ABI", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "transfer",
          inputs: [{ name: "to", type: "address" }],
        },
      ];

      const result = extractFunctionArgs(abi, "nonExistent", ["0xaddr"]);
      expect(result).to.be.undefined;
    });

    it("should handle functions with no inputs", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "totalSupply",
          inputs: [],
        },
      ];

      const result = extractFunctionArgs(abi, "totalSupply", []);
      expect(result).to.deep.equal({});
    });

    it("should handle functions with fewer args than inputs", () => {
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "transfer",
          inputs: [
            { name: "to", type: "address" },
            { name: "amount", type: "uint256" },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "transfer", ["0xaddr"]);
      expect(result).to.deep.equal({
        to: "0xaddr",
      });
    });

    it("should filter out non-function ABI items", () => {
      const abi: AbiItem[] = [
        {
          type: "event",
          name: "Transfer",
          inputs: [{ name: "from", type: "address", indexed: true }],
        },
        {
          type: "function",
          name: "Transfer",
          inputs: [{ name: "to", type: "address" }],
        },
      ];

      const result = extractFunctionArgs(abi, "Transfer", ["0xaddr"]);
      expect(result).to.deep.equal({
        to: "0xaddr",
      });
    });

    it("should handle nested structs with BigInt values", () => {
      // Simulates a Solidity function like:
      // struct Order { address maker; uint256 price; uint256 amount; }
      // function submitOrder(Order calldata order) external;
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "submitOrder",
          inputs: [
            {
              name: "order",
              type: "tuple",
              components: [
                { name: "maker", type: "address" },
                { name: "price", type: "uint256" },
                { name: "amount", type: "uint256" },
              ],
            },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "submitOrder", [
        {
          maker: "0x1234567890123456789012345678901234567890",
          price: BigInt("1000000000000000000"),
          amount: BigInt("50000000"),
        },
      ]);

      expect(result).to.deep.equal({
        order: {
          maker: "0x1234567890123456789012345678901234567890",
          price: "1000000000000000000",
          amount: "50000000",
        },
      });
    });

    it("should handle array of structs with BigInt values", () => {
      // Simulates a Solidity function like:
      // struct Transfer { address to; uint256 amount; }
      // function batchTransfer(Transfer[] calldata transfers) external;
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "batchTransfer",
          inputs: [
            {
              name: "transfers",
              type: "tuple[]",
              components: [
                { name: "to", type: "address" },
                { name: "amount", type: "uint256" },
              ],
            },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "batchTransfer", [
        [
          { to: "0xaddr1", amount: BigInt(100) },
          { to: "0xaddr2", amount: BigInt(200) },
        ],
      ]);

      expect(result).to.deep.equal({
        transfers: [
          { to: "0xaddr1", amount: "100" },
          { to: "0xaddr2", amount: "200" },
        ],
      });
    });

    it("should handle deeply nested structs with BigInt values", () => {
      // Simulates a Solidity function like:
      // struct TokenAmount { address token; uint256 amount; }
      // struct SwapParams { TokenAmount input; TokenAmount output; uint256 deadline; }
      // function swap(SwapParams calldata params) external;
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "swap",
          inputs: [
            {
              name: "params",
              type: "tuple",
              components: [
                {
                  name: "input",
                  type: "tuple",
                  components: [
                    { name: "token", type: "address" },
                    { name: "amount", type: "uint256" },
                  ],
                },
                {
                  name: "output",
                  type: "tuple",
                  components: [
                    { name: "token", type: "address" },
                    { name: "amount", type: "uint256" },
                  ],
                },
                { name: "deadline", type: "uint256" },
              ],
            },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "swap", [
        {
          input: {
            token: "0xtoken1",
            amount: BigInt("1000000000000000000"),
          },
          output: {
            token: "0xtoken2",
            amount: BigInt("950000000000000000"),
          },
          deadline: BigInt("1700000000"),
        },
      ]);

      expect(result).to.deep.equal({
        params: {
          input: {
            token: "0xtoken1",
            amount: "1000000000000000000",
          },
          output: {
            token: "0xtoken2",
            amount: "950000000000000000",
          },
          deadline: "1700000000",
        },
      });
    });

    it("should handle multi-dimensional arrays with BigInt values", () => {
      // Simulates a Solidity function like:
      // function processMatrix(uint256[][] calldata matrix) external;
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "processMatrix",
          inputs: [{ name: "matrix", type: "uint256[][]" }],
        },
      ];

      const result = extractFunctionArgs(abi, "processMatrix", [
        [
          [BigInt(1), BigInt(2), BigInt(3)],
          [BigInt(4), BigInt(5), BigInt(6)],
        ],
      ]);

      expect(result).to.deep.equal({
        matrix: [
          ["1", "2", "3"],
          ["4", "5", "6"],
        ],
      });
    });

    it("should handle mixed nested structures with BigInt", () => {
      // Complex case: array of structs containing arrays
      const abi: AbiItem[] = [
        {
          type: "function",
          name: "complexCall",
          inputs: [
            {
              name: "data",
              type: "tuple[]",
              components: [
                { name: "amounts", type: "uint256[]" },
                { name: "flag", type: "bool" },
              ],
            },
          ],
        },
      ];

      const result = extractFunctionArgs(abi, "complexCall", [
        [
          { amounts: [BigInt(100), BigInt(200)], flag: true },
          { amounts: [BigInt(300)], flag: false },
        ],
      ]);

      expect(result).to.deep.equal({
        data: [
          { amounts: ["100", "200"], flag: true },
          { amounts: ["300"], flag: false },
        ],
      });
    });
  });

  describe("buildSafeFunctionArgs", () => {
    const RESERVED_FIELDS = new Set([
      "status",
      "chainId",
      "address",
      "data",
      "to",
      "value",
      "transactionHash",
      "function_name",
      "function_args",
    ]);

    it("should return undefined for undefined input", () => {
      const result = buildSafeFunctionArgs(undefined, RESERVED_FIELDS);
      expect(result).to.be.undefined;
    });

    it("should prefix reserved field names with arg_", () => {
      const result = buildSafeFunctionArgs(
        { to: "0xRecipient", amount: "100" },
        RESERVED_FIELDS
      );
      expect(result).to.deep.equal({
        arg_to: "0xRecipient",
        amount: "100",
      });
    });

    it("should flatten nested structs", () => {
      const result = buildSafeFunctionArgs(
        {
          order: {
            maker: "0xMaker",
            price: "1000",
          },
        },
        RESERVED_FIELDS
      );
      expect(result).to.deep.equal({
        order: { maker: "0xMaker", price: "1000" },
        order_maker: "0xMaker",
        order_price: "1000",
      });
    });

    it("should skip flattened keys that collide with existing args", () => {
      const result = buildSafeFunctionArgs(
        {
          config_value: "999",
          config: { value: "123", other: "456" },
        },
        RESERVED_FIELDS
      );
      expect(result).to.deep.equal({
        config_value: "999",
        config: { value: "123", other: "456" },
        config_other: "456",
      });
    });

    it("should handle reserved field name with nested struct", () => {
      const result = buildSafeFunctionArgs(
        {
          to: { recipient: "0xAddr", chainId: "137" },
        },
        RESERVED_FIELDS
      );
      expect(result).to.deep.equal({
        arg_to: { recipient: "0xAddr", chainId: "137" },
        arg_to_recipient: "0xAddr",
        arg_to_chainId: "137",
      });
    });
  });
});

